def decode(data, pos=0):
    b=data[pos]; pos+=1
    major=b>>5; ai=b&31
    def get_ai(ai,pos):
        if ai<24: return ai,pos
        if ai==24: v=data[pos]; return v,pos+1
        if ai==25: v=int.from_bytes(data[pos:pos+2],'big'); return v,pos+2
        if ai==26: v=int.from_bytes(data[pos:pos+4],'big'); return v,pos+4
        if ai==27: v=int.from_bytes(data[pos:pos+8],'big'); return v,pos+8
        if ai==31: return None,pos
        raise ValueError(ai)
    if major==0:
        v,pos=get_ai(ai,pos); return v,pos
    if major==1:
        v,pos=get_ai(ai,pos); return -1-v,pos
    if major==2:
        v,pos=get_ai(ai,pos); s=data[pos:pos+v]; return s,pos+v
    if major==3:
        v,pos=get_ai(ai,pos); s=data[pos:pos+v].decode(); return s,pos+v
    if major==4:
        v,pos=get_ai(ai,pos); arr=[]
        if v is None:
            while data[pos]!=0xff:
                item,pos=decode(data,pos); arr.append(item)
            return arr,pos+1
        for _ in range(v):
            item,pos=decode(data,pos); arr.append(item)
        return arr,pos
    if major==5:
        v,pos=get_ai(ai,pos); m={}
        for _ in range(v):
            k,pos=decode(data,pos); val,pos=decode(data,pos); m[k]=val
        return m,pos
    if major==6:
        v,pos=get_ai(ai,pos); val,pos=decode(data,pos); return ('tag',v,val),pos
    if major==7:
        if ai==20: return False,pos
        if ai==21: return True,pos
        if ai==22: return None,pos
        if ai==23: return ('undef',),pos
        if ai==25: 
            import struct; v=struct.unpack('>e', data[pos:pos+2])[0]; return v,pos+2
        if ai==26:
            import struct; v=struct.unpack('>f', data[pos:pos+4])[0]; return v,pos+4
        if ai==27:
            import struct; v=struct.unpack('>d', data[pos:pos+8])[0]; return v,pos+8
        raise ValueError(f"simple {ai}")
    raise ValueError(major)

def encode(obj):
    if obj is None: return b'\xf6'
    if obj is False: return b'\xf4'
    if obj is True: return b'\xf5'
    if isinstance(obj,int):
        if obj>=0: return encode_major(0,obj)
        else: return encode_major(1,-1-obj)
    if isinstance(obj,str):
        b=obj.encode(); return encode_major(3,len(b))+b
    if isinstance(obj,bytes):
        return encode_major(2,len(obj))+obj
    if isinstance(obj,(list,tuple)):
        out=encode_major(4,len(obj))
        for i in obj: out+=encode(i)
        return out
    if isinstance(obj,dict):
        out=encode_major(5,len(obj))
        for k,v in obj.items(): out+=encode(k)+encode(v)
        return out
    if isinstance(obj,float):
        import struct; return b'\xfb'+struct.pack('>d',obj)
    raise TypeError(obj)
def encode_major(major, v):
    mt=major<<5
    if v<24: return bytes([mt|v])
    if v<256: return bytes([mt|24, v])
    if v<65536: return bytes([mt|25])+v.to_bytes(2,'big')
    if v<4294967296: return bytes([mt|26])+v.to_bytes(4,'big')
    return bytes([mt|27])+v.to_bytes(8,'big')
