import socket, os, sys, struct
sys.path.insert(0,'/tmp')
from cbor import decode
path="/home/agent/.local/share/pueue/pueue_agent.socket"
try: os.unlink(path)
except: pass
s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.bind(path); s.listen(5); s.settimeout(10)
conn,_=s.accept(); conn.settimeout(5)
def recv_exact(n):
    d=b""
    while len(d)<n:
        c=conn.recv(n-len(d))
        if not c: raise EOFError("eof")
        d+=c
    return d
def recv_msg():
    hdr=recv_exact(8); ln=int.from_bytes(hdr,'big'); data=recv_exact(ln)
    return data
def send_msg(data): conn.sendall(struct.pack(">Q", len(data))+data)
try:
    recv_msg(); send_msg(b"testversion")
    data=recv_msg()
    print("RAW",data.hex(), flush=True)
    try:
        obj,pos=decode(data)
        print("DECODED",repr(obj), "pos",pos, flush=True)
    except Exception as e: print("decode err",e, flush=True)
    conn.settimeout(2)
    try:
        while True:
            d=recv_msg(); print("NEXT",d, flush=True)
    except Exception as e: print("next err",e, flush=True)
except Exception as e: print("err",e, flush=True)
