sys.path.insert(0,'/tmp'); from cbor import encode, decode
path="/home/agent/.local/share/pueue/pueue_agent.socket"
def serve_convo(responses):
    try: os.unlink(path)
    except: pass
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.bind(path); s.listen(1); s.settimeout(10)
    reqs=[]
    def serve():
        try:
            conn,_=s.accept(); conn.settimeout(10)
            def recv_exact(n):
                d=b""
                while len(d)<n:
                    c=conn.recv(n-len(d))
                    if not c: raise EOFError("eof")
                    d+=c
                return d
            def recv_msg():
                hdr=recv_exact(8); ln=int.from_bytes(hdr,'big'); return recv_exact(ln)
            def send_msg(b): conn.sendall(struct.pack(">Q", len(b))+b)
            recv_msg(); send_msg(b"testversion")
            for resp in responses:
                try: req=recv_msg()
                except Exception as e: reqs.append(("EOF",str(e))); break
                try: decoded=decode(req)[0]
                except: decoded=req.hex()
                reqs.append(decoded)
                if resp is None: continue
                # resp may be callable
