                    req=recv_msg(); reqs.append(decode(req)[0])
            except: pass
            conn.close()
        except Exception as e: reqs.append(("serveerr",str(e)))
        finally: s.close()
    t=threading.Thread(target=serve,daemon=True); t.start()
    return t, reqs

