import socket, os, struct, subprocess, threading, time, re
path="/home/agent/.local/share/pueue/pueue_agent.socket"
def run(mode):
    try: os.unlink(path)
    except: pass
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.bind(path); s.listen(1); s.settimeout(5)
    def serve():
        try:
            conn,_=s.accept(); conn.settimeout(5)
            def recv_exact(n):
                d=b""
                while len(d)<n:
                    c=conn.recv(n-len(d))
                    if not c: raise EOFError()
                    d+=c
                return d
            hdr=recv_exact(8); ln=int.from_bytes(hdr,'big'); recv_exact(ln)
            if mode=="close": pass
            elif mode=="partial_header": conn.sendall(b"\x00\x00")
            elif mode=="partial_payload": conn.sendall(struct.pack(">Q",10)+b"abc")
            elif mode=="invalid_utf8": conn.sendall(struct.pack(">Q",3)+b"\xff\xfe\xfd")
            elif mode=="huge_len": conn.sendall(struct.pack(">Q",999999999))
            elif mode=="version_then_close": conn.sendall(struct.pack(">Q",3)+b"1.0")
            time.sleep(0.5)
            conn.close()
        except Exception as e: print("serve",e)
        finally: s.close()
