use serde::{Serialize,Deserialize};
use std::collections::BTreeMap;
#[derive(Serialize,Deserialize,Debug,Clone)]
enum TaskStatus {
    Queued { enqueued_at: String },
    Stashed { enqueue_at: Option<String> },
    Done { enqueued_at: String, start: String, end: String, result: TaskResult },
}
#[derive(Serialize,Deserialize,Debug,Clone)]
enum TaskResult { Success, Failed(i32) }
#[derive(Serialize,Deserialize,Debug,Clone)]
struct Task { id: usize, created_at: String, original_command: String, command: String, path: String, envs: BTreeMap<String,String>, group: String, dependencies: Vec<usize>, priority: i32, label: Option<String>, status: TaskStatus }
#[derive(Serialize,Deserialize,Debug)]
enum Msg {
    AddedTask { message: String, task_id: usize },
    Edit(Vec<Task>),
    Status(String),
    Log(BTreeMap<usize,(Task, Option<String>)>),
    Group(String),
    Stream(String),
    Success(String),
    Failure(String),
    Close,
}
fn main(){
    let dt="2026-09-29T08:00:00Z".to_string();
    let task=Task{id:0,created_at:"2026-09-29T10:00:00+00:00".into(),original_command:"echo hi".into(),command:"echo hi".into(),path:"/tmp".into(),envs:BTreeMap::new(),group:"default".into(),dependencies:vec![],priority:0,label:None,status:TaskStatus::Done{enqueued_at:dt.clone(),start:dt.clone(),end:dt.clone(),result:TaskResult::Success}};
    let mut map=BTreeMap::new(); map.insert(0usize,(task.clone(), Some("out\n".to_string())));
    let vals:Vec<(&str,Msg)> = vec![
        ("log_pair", Msg::Log(map)),
        ("added", Msg::AddedTask{message:"hi".into(),task_id:0}),
    ];
    for (name,v) in &vals {
        let mut buf=Vec::new(); ciborium::into_writer(v,&mut buf).unwrap();
        std::fs::write(format!("/tmp/{}.cbor",name), &buf).unwrap();
        println!("{} {}",name, buf.iter().map(|x|format!("{:02x}",x)).collect::<String>());
    }
}
