import socket, os, struct, subprocess, threading, sys
path="/home/agent/.local/share/pueue/pueue_agent.socket"
def run_file(fname, args):
    payload=open(fname,'rb').read()
    try: os.unlink(path)
    except: pass
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.bind(path); s.listen(1); s.settimeout(5)
    def serve():
        try:
            conn,_=s.accept(); conn.settimeout(5)
            def recv_exact(n):
                d=b""
                while len(d)<n:
                    c=conn.recv(n-len(d))
                    if not c: raise EOFError()
                    d+=c
                return d
            def recv_msg():
                hdr=recv_exact(8); ln=int.from_bytes(hdr,'big'); return recv_exact(ln)
            recv_msg(); conn.sendall(struct.pack(">Q", len(b"testversion"))+b"testversion"); recv_msg(); conn.sendall(struct.pack(">Q", len(payload))+payload); conn.close()
        except: pass
        finally: s.close()
    import threading; t=threading.Thread(target=serve,daemon=True); t.start()
    r=subprocess.run(['/workspace/executable','-c','/tmp/pueue_test/empty.yml']+args, cwd='/tmp', capture_output=True, text=True, timeout=5); t.join(2); print(fname,args,r.returncode,repr(r.stdout),repr(r.stderr[:300]))
run_file("/tmp/log_pair.cbor", ['log','0'])
