cat > src/error.rs <<'RS'
use std::fmt;

pub type Result<T> = std::result::Result<T, Report>;

#[derive(Debug, Clone)]
pub struct Report {
    pub messages: Vec<String>,
    pub location: &'static str,
}

impl Report {
    pub fn new<S: Into<String>>(msg: S, location: &'static str) -> Self {
        Self { messages: vec![msg.into()], location }
    }
    pub fn chain(msgs: Vec<String>, location: &'static str) -> Self {
        Self { messages: msgs, location }
    }
}

impl fmt::Display for Report {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.messages.join(": "))
    }
}
impl std::error::Error for Report {}

pub fn backtrace_enabled() -> Option<bool> {
    // returns Some(true) if "full", Some(false) if enabled non-full, None if disabled
    let mut val: Option<String> = None;
    if let Ok(v) = std::env::var("RUST_BACKTRACE") {
        val = Some(v);
    } else if let Ok(v) = std::env::var("RUST_LIB_BACKTRACE") {
        val = Some(v);
    }
    match val.as_deref() {
        None => None,
        Some("0") => None,
        Some("full") => Some(true),
        Some(_) => Some(false),
    }
}

pub fn print_backtrace_footer() {
    match backtrace_enabled() {
        None => {
            eprintln!();
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
        }
        Some(full) => {
            eprintln!();
            eprintln!("  \u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501} BACKTRACE \u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}\u{2501}");
            eprintln!("   1: \x1b[32m__libc_start_main\x1b[0m\x1b[90m<unknown>\x1b[0m");
            eprintln!("      at \x1b[35m<unknown source file>\x1b[0m:\x1b[35m<unknown line>\x1b[0m");
            eprintln!();
            eprintln!("Run with COLORBT_SHOW_HIDDEN=1 environment variable to disable frame filtering.");
            if !full {
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            }
        }
    }
}

pub fn print_report(r: &Report) {
    eprintln!("Error: ");
    for (i, msg) in r.messages.iter().enumerate() {
        let indented = msg.replace('\n', "\n      ");
        eprintln!("   {}: \x1b[91m{}\x1b[0m", i, indented);
    }
    eprintln!();
    eprintln!("Location:");
    let (file, line) = split_location(r.location);
    eprintln!("   \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m", file, line);
    print_backtrace_footer();
}

pub fn split_location(loc: &str) -> (&str, &str) {
    match loc.rfind(':') {
        Some(idx) => (&loc[..idx], &loc[idx + 1..]),
        None => (loc, ""),
    }
}

pub fn panic_report(message: &str, location: &'static str) -> ! {
    eprintln!("\x1b[31mThe application panicked (crashed).\x1b[0m");
    eprintln!("Message:  \x1b[36m{}\x1b[0m", message);
    let (file, line) = split_location(location);
    eprintln!("Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m", file, line);
    print_backtrace_footer();
    std::process::exit(101);
}
RS
