use std::sync::atomic::{AtomicU8, Ordering};

pub static VERBOSE: AtomicU8 = AtomicU8::new(0);

pub fn verbose() -> u8 { VERBOSE.load(Ordering::Relaxed) }

// level: 0 error, 1 warn, 2 info, 3 debug, 4 trace
pub fn enabled(level: u8) -> bool {
    let v = verbose();
    let threshold = match v {
        0 => 1, // warn
        1 => 2, // info
        2 => 3, // debug
        _ => 4, // trace
    };
    level <= threshold
}

fn level_name(level: u8) -> &'static str {
    match level { 0 => "ERROR", 1 => " WARN", 2 => " INFO", 3 => "DEBUG", _ => "TRACE" }
}
fn level_color(level: u8) -> u8 {
    match level { 0 => 31, 1 => 33, 2 => 32, 3 => 34, _ => 35 }
}
fn timestamp() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}

pub fn log_event(level: u8, target: &str, location: &'static str, message: &str) {
    log_event_fmt(level, target, location, message, None);
}

/// For the tracing structured event (Handling command). compact_field is `subcommand=...`, pretty_field is `subcommand: ...`
pub fn log_event_fmt(level: u8, target: &str, location: &'static str, message: &str, field: Option<(&str, &str, &str)>) {
    // field = (compact_render, pretty_render, field_name)
    if !enabled(level) { return; }
    let color = level_color(level);
    let name = level_name(level);
    if verbose() >= 4 {
        // pretty
        eprintln!();
        if let Some((_, pretty_val, field_name)) = field {
            eprintln!("  \x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[1;{}m{}\x1b[0m\x1b[{}m: \x1b[{}m{}, \x1b[1;{}m{}\x1b[0m\x1b[{}m: {}\x1b[0m", timestamp(), color, name, color, target, color, color, message, color, field_name, color, pretty_val);
        } else {
            eprintln!("  \x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[1;{}m{}\x1b[0m\x1b[{}m: \x1b[{}m{}\x1b[0m", timestamp(), color, name, color, target, color, color, message);
        }
        let (file, line) = crate::error::split_location(location);
        eprintln!("    \x1b[2;3mat\x1b[0m {}:{} \x1b[2;3mon\x1b[0m main", file, line);
    } else {
        if let Some((compact_val, _, field_name)) = field {
            eprintln!("\x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {} {}={}", timestamp(), color, name, target, message, field_name, compact_val);
        } else {
            eprintln!("\x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}", timestamp(), color, name, target, message);
        }
    }
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $loc:expr, $($arg:tt)*) => { $crate::log::log_event(0, $target, $loc, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_warn {
    ($target:expr, $loc:expr, $($arg:tt)*) => { $crate::log::log_event(1, $target, $loc, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_info {
    ($target:expr, $loc:expr, $($arg:tt)*) => { $crate::log::log_event(2, $target, $loc, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_debug {
    ($target:expr, $loc:expr, $($arg:tt)*) => { $crate::log::log_event(3, $target, $loc, &format!($($arg)*)) };
}
RS
"}

