    }
    candidates.push(PathBuf::from("./pueue.yml"));
    let mut found: Option<PathBuf> = None;
    for cand in &candidates {
        crate::log_info!("pueue_lib::settings", "pueue_lib/src/settings.rs:396", "Checking path: {:?}", cand.to_string_lossy().to_string());
        // The log message uses quoted path string as in Rust Debug for Path? Original: Checking path: "/home/..."
