        }
    };
    serde_yaml::from_str::<Settings>(&text).map_err(|e| {
        Report::chain(vec!["Failed to read configuration.".to_string(), format!("Error while reading configuration:\n{}", e)], "pueue/src/bin/pueue.rs:51")
    })
}
