    }
    // getpwuid fallback
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if !pw.is_null() {
            let dir = std::ffi::CStr::from_ptr((*pw).pw_dir).to_string_lossy().into_owned();
            if !dir.is_empty() { return Some(PathBuf::from(dir)); }
        }
    }
