        return Ok(LoadedSettings { settings, config_found: true });
    }
    crate::log_info!("pueue_lib::settings", "pueue_lib/src/settings.rs:413", "No config file found. Use default config.");
    Ok(LoadedSettings { settings: Settings::default(), config_found: false })
}

fn read_config_file(path_str: &str) -> std::result::Result<Settings, Report> {
    let file = std::fs::File::open(path_str).map_err(|e| {
        Report::chain(vec!["Failed to read configuration.".to_string(), format!("I/O error at path {:?} while opening config file:\n{}", path_str, e)], "pueue/src/bin/pueue.rs:51")
    })?;
    read_from_file(file)
}
fn read_config_file_path(path: &PathBuf) -> std::result::Result<Settings, Report> {
    let disp = path.to_string_lossy().to_string();
