    let file = std::fs::File::open(path).map_err(|e| {
        Report::chain(vec!["Failed to read configuration.".to_string(), format!("I/O error at path {:?} while opening config file:\n{}", disp, e)], "pueue/src/bin/pueue.rs:51")
    })?;
    read_from_file(file)
}
fn read_from_file(mut file: std::fs::File) -> std::result::Result<Settings, Report> {
    use std::io::Read;
    let mut content = Vec::new();
    if let Err(e) = file.read_to_end(&mut content) {
        return Err(Report::chain(vec!["Failed to read configuration.".to_string(), format!("Error while reading configuration:\n{}", e)], "pueue/src/bin/pueue.rs:51"));
