use chrono::{DateTime, Local};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::path::PathBuf;

pub type TaskId = usize;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum TaskResult {
    Success,
    Failed(i32),
    FailedToSpawn(String),
    DependencyFailed,
    Errored,
    Killed,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum TaskStatus {
    Locked { previous_status: Box<TaskStatus> },
    Stashed { enqueue_at: Option<DateTime<Local>> },
    Queued { enqueued_at: DateTime<Local> },
    Running { enqueued_at: DateTime<Local>, start: DateTime<Local> },
    Paused { enqueued_at: DateTime<Local>, start: DateTime<Local> },
    Done { enqueued_at: DateTime<Local>, start: DateTime<Local>, end: DateTime<Local>, result: TaskResult },
}

impl TaskStatus {
    pub fn is_done(&self) -> bool { matches!(self, TaskStatus::Done { .. }) }
    // helpers for display
    pub fn start(&self) -> Option<DateTime<Local>> {
        match self {
            TaskStatus::Running { start, .. } | TaskStatus::Paused { start, .. } | TaskStatus::Done { start, .. } => Some(*start),
            _ => None,
        }
    }
    pub fn end(&self) -> Option<DateTime<Local>> {
        match self { TaskStatus::Done { end, .. } => Some(*end), _ => None }
    }
    pub fn enqueue_at(&self) -> Option<DateTime<Local>> {
        match self {
            TaskStatus::Stashed { enqueue_at } => *enqueue_at,
            TaskStatus::Queued { enqueued_at } => Some(*enqueued_at),
            TaskStatus::Running { enqueued_at, .. } | TaskStatus::Paused { enqueued_at, .. } | TaskStatus::Done { enqueued_at, .. } => Some(*enqueued_at),
            TaskStatus::Locked { previous_status } => previous_status.enqueue_at(),
        }
    }
    pub fn display_status(&self) -> String {
        match self {
            TaskStatus::Locked { .. } => "Locked".to_string(),
            TaskStatus::Stashed { .. } => "Stashed".to_string(),
            TaskStatus::Queued { .. } => "Queued".to_string(),
            TaskStatus::Running { .. } => "Running".to_string(),
            TaskStatus::Paused { .. } => "Paused".to_string(),
            TaskStatus::Done { result, .. } => match result {
                TaskResult::Success => "Success".to_string(),
                TaskResult::Failed(code) => format!("Failed ({})", code),
                TaskResult::FailedToSpawn(_) => "Failed to spawn".to_string(),
                TaskResult::DependencyFailed => "Dependency failed".to_string(),
                TaskResult::Errored => "Errored".to_string(),
                TaskResult::Killed => "Killed".to_string(),
            },
        }
    }
}

#[derive(Clone, Serialize, Deserialize)]
pub struct Task {
    pub id: TaskId,
    pub created_at: DateTime<Local>,
    pub original_command: String,
    pub command: String,
    pub path: PathBuf,
    pub envs: HashMap<String, String>,
    pub group: String,
    pub dependencies: Vec<TaskId>,
    pub priority: i32,
    #[serde(default)]
    pub label: Option<String>,
    pub status: TaskStatus,
}

impl std::fmt::Debug for Task {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Custom debug matching original: envs hidden, created_at skipped, fields order below
        f.debug_struct("Task")
            .field("id", &self.id)
            .field("original_command", &self.original_command)
            .field("command", &self.command)
            .field("path", &self.path)
            .field("envs", &"hidden")
            .field("group", &self.group)
            .field("dependencies", &self.dependencies)
            .field("label", &self.label)
            .field("status", &self.status)
            .field("priority", &self.priority)
            .finish()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum GroupStatus {
    Running,
    Paused,
}
impl GroupStatus {
    pub fn display(&self) -> &'static str {
        match self { GroupStatus::Running => "running", GroupStatus::Paused => "paused" }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Group {
    pub status: GroupStatus,
    pub parallel_tasks: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct State {
    #[serde(default)]
    pub tasks: BTreeMap<TaskId, Task>,
    #[serde(default)]
    pub groups: BTreeMap<String, Group>,
}

// ---------- Requests ----------
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum TaskSelection {
    TaskIds(Vec<TaskId>),
    Group(String),
    All,
}

#[derive(Clone, Serialize, Deserialize)]
pub struct AddTask {
    pub command: String,
    pub path: PathBuf,
    pub envs: HashMap<String, String>,
    pub start_immediately: bool,
    pub stashed: bool,
    pub group: String,
    pub enqueue_at: Option<DateTime<Local>>,
    pub dependencies: Vec<TaskId>,
    pub priority: Option<i32>,
    pub label: Option<String>,
}
impl std::fmt::Debug for AddTask {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Task")
            .field("command", &self.command)
            .field("path", &self.path)
            .field("envs", &"hidden")
            .field("start_immediately", &self.start_immediately)
            .field("stashed", &self.stashed)
            .field("group", &self.group)
            .field("enqueue_at", &self.enqueue_at)
            .field("dependencies", &self.dependencies)
            .field("label", &self.label)
            .finish()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SwitchMessage {
    pub task_id_1: TaskId,
    pub task_id_2: TaskId,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StashMessage {
    pub tasks: TaskSelection,
    pub enqueue_at: Option<DateTime<Local>>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnqueueMessage {
    pub tasks: TaskSelection,
    pub enqueue_at: Option<DateTime<Local>>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StartMessage {
    pub tasks: TaskSelection,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PauseMessage {
    pub tasks: TaskSelection,
    pub wait: bool,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Copy)]
pub enum Signal {
    SigInt,
    SigKill,
    SigTerm,
    SigCont,
    SigStop,
}
impl std::str::FromStr for Signal {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        // Case-insensitive, optional SIG prefix, numeric forms
        let lower = s.to_ascii_lowercase();
        let stripped = lower.strip_prefix("sig").unwrap_or(&lower);
        match stripped {
            "int" | "2" => Ok(Signal::SigInt),
            "kill" | "9" => Ok(Signal::SigKill),
            "term" | "15" => Ok(Signal::SigTerm),
            "cont" | "18" => Ok(Signal::SigCont),
            "stop" | "19" => Ok(Signal::SigStop),
            _ => Err("Matching variant not found".to_string()),
        }
    }
}
impl Signal {
    pub fn all_names() -> Vec<String> {
        vec![]
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KillMessage {
    pub tasks: TaskSelection,
    pub signal: Option<Signal>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SendMessage {
    pub task_id: TaskId,
    pub input: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum EnvMessage {
    Set { task_id: TaskId, key: String, value: String },
    Unset { task_id: TaskId, key: String },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum GroupMessage {
    List,
    Add { name: String, parallel_tasks: Option<usize> },
    Remove(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogMessage {
    pub tasks: TaskSelection,
    pub send_logs: bool,
    pub lines: Option<usize>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CleanMessage {
    pub successful_only: bool,
    pub group: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ParallelMessage {
    pub parallel_tasks: usize,
    pub group: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Shutdown {
    Graceful,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RestartTask {
    pub task_id: TaskId,
    pub original_command: String,
    pub path: PathBuf,
    pub label: Option<String>,
    pub priority: i32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RestartMessage {
    pub tasks: Vec<RestartTask>,
    pub start_immediately: bool,
    pub stashed: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EditableTask {
    pub id: TaskId,
    pub command: String,
    pub path: PathBuf,
    pub label: Option<String>,
    pub priority: i32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[allow(clippy::large_enum_variant)]
pub enum Request {
    Add(AddTask),
    Remove(Vec<TaskId>),
    Switch(SwitchMessage),
    Stash(StashMessage),
    Enqueue(EnqueueMessage),
    Start(StartMessage),
    Pause(PauseMessage),
    Kill(KillMessage),
    Send(SendMessage),
    EditRequest(Vec<TaskId>),
    EditRestore(Vec<TaskId>),
    EditedTasks(Vec<EditableTask>),
    Env(EnvMessage),
    Group(GroupMessage),
    Status,
    Log(LogMessage),
    StreamRequest(TaskId),
    Clean(CleanMessage),
    Parallel(ParallelMessage),
    DaemonShutdown(Shutdown),
    Restart(RestartMessage),
}

// Responses
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GroupResponse {
    pub groups: BTreeMap<String, Group>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AddedTaskResponse {
