}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[allow(clippy::large_enum_variant)]
pub enum Response {
    AddedTask(AddedTaskResponse),
    Edit(Vec<Task>),
    Status(State),
    Log(BTreeMap<TaskId, LogEntry>),
    Group(GroupResponse),
    Stream(String),
    Success(String),
    Failure(String),
    Close,
}
RS
