import socket, os, struct, subprocess, threading, re
path="/home/agent/.local/share/pueue/pueue_agent.socket"
def run(size):
    try: os.unlink(path)
    except: pass
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.bind(path); s.listen(1); s.settimeout(5)
    def serve():
        try:
            conn,_=s.accept(); conn.settimeout(5)
            def recv_exact(n):
                d=b""
                while len(d)<n:
                    c=conn.recv(n-len(d))
                    if not c: raise EOFError()
                    d+=c
                return d
            hdr=recv_exact(8); ln=int.from_bytes(hdr,'big'); recv_exact(ln)
            conn.sendall(struct.pack(">Q", size))
            import time; time.sleep(0.3); conn.close()
        except: pass
        finally: s.close()
    t=threading.Thread(target=serve,daemon=True); t.start()
    r=subprocess.run(['/tmp/original_executable','-c','/tmp/pueue_test/empty.yml','status'], cwd='/tmp', capture_output=True, text=True, timeout=5)
    t.join(2)
    print(size, "large warn" in r.stderr, [l for l in r.stderr.splitlines() if 'large' in l])
