use crate::error::{Report, Result};
use crate::message::{Request, Response};
use std::io::{Read, Write};

pub const PROTOCOL_VERSION: &str = "0.5.0"; // placeholder, to be determined

#[derive(Debug)]
pub struct ProtoError {
    pub message: String,
}
impl ProtoError {
    pub fn to_report(&self, location: &'static str) -> Report {
        Report::new(self.message.clone(), location)
    }
}
pub type ProtoResult<T> = std::result::Result<T, ProtoError>;

fn io_display(e: &std::io::Error) -> String {
    if e.kind() == std::io::ErrorKind::UnexpectedEof {
        "early eof".to_string()
    } else {
        format!("{}", e)
    }
}

pub trait Transport: Read + Write {}
impl Transport for std::os::unix::net::UnixStream {}
impl Transport for std::net::TcpStream {}

pub struct TlsTransport {
    pub child: std::process::Child,
    pub stdin: Option<std::process::ChildStdin>,
    pub stdout: Option<std::process::ChildStdout>,
}
impl Read for TlsTransport {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        match &mut self.stdout {
            Some(out) => out.read(buf),
            None => Ok(0),
        }
    }
}
impl Write for TlsTransport {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match &mut self.stdin {
            Some(inp) => inp.write(buf),
            None => Err(std::io::Error::new(std::io::ErrorKind::BrokenPipe, "tls closed")),
        }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        match &mut self.stdin { Some(inp) => inp.flush(), None => Ok(()) }
    }
}
impl Transport for TlsTransport {}

pub type BoxTransport = Box<dyn Transport + Send>;

pub fn send_bytes(stream: &mut BoxTransport, bytes: &[u8]) -> ProtoResult<()> {
    let len = bytes.len() as u64;
    stream.write_all(&len.to_be_bytes()).map_err(|e| ProtoError { message: format!("I/O error while sending payload:\n{}", io_display(&e)) })?;
    stream.write_all(bytes).map_err(|e| ProtoError { message: format!("I/O error while sending payload:\n{}", io_display(&e)) })?;
    stream.flush().map_err(|e| ProtoError { message: format!("I/O error while sending payload:\n{}", io_display(&e)) })?;
    Ok(())
}

pub fn recv_bytes(stream: &mut BoxTransport) -> ProtoResult<Vec<u8>> {
    let mut header = [0u8; 8];
    // read_exact equivalent
    let mut read = 0usize;
    while read < 8 {
        match stream.read(&mut header[read..]) {
            Ok(0) => {
                return Err(ProtoError { message: "I/O error while reading request size header:\nearly eof".to_string() });
            }
            Ok(n) => read += n,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::UnexpectedEof {
                    return Err(ProtoError { message: "I/O error while reading request size header:\nearly eof".to_string() });
                }
                return Err(ProtoError { message: format!("I/O error while reading request size header:\n{}", io_display(&e)) });
            }
        }
    }
    let len = u64::from_be_bytes(header);
    if len > 20_971_520 {
        crate::log_warn!("pueue_lib::network::protocol", "pueue_lib/src/network/protocol.rs:126", "Client is sending a large payload: {} bytes.", len);
    }
