    let mut buf = Vec::new();
    // Read in chunks, avoid huge preallocation beyond some cap
    let mut remaining = len_usize;
    let mut chunk = vec![0u8; 8192];
    while remaining > 0 {
        let to_read = std::cmp::min(remaining, chunk.len());
        match stream.read(&mut chunk[..to_read]) {
            Ok(0) => {
                return Err(ProtoError { message: "Connection went away while receiving payload.".to_string() });
            }
            Ok(n) => {
                buf.extend_from_slice(&chunk[..n]);
                remaining -= n;
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::UnexpectedEof {
                    return Err(ProtoError { message: "Connection went away while receiving payload.".to_string() });
                }
                // For reset etc, original handling in read for payload? It treated interrupted?
                // If connection reset while expecting payload, map to went away? Observed for header reset case, not payload.
                // We'll return went away for any error after header? But need inspect later.
                return Err(ProtoError { message: format!("{}", io_display(&e)) });
            }
        }
    }
    Ok(buf)
}

pub fn send_request(stream: &mut BoxTransport, request: &Request) -> ProtoResult<()> {
    crate::log_debug!("pueue_lib::network::protocol", "pueue_lib/src/network/protocol.rs:50", "Sending message: {:#?}", request);
    let mut bytes = Vec::new();
    ciborium::into_writer(request, &mut bytes).map_err(|e| ProtoError { message: format!("Couldn't serialize message:\n{}", e) })?;
    send_bytes(stream, &bytes)
}

pub fn receive_response(stream: &mut BoxTransport) -> ProtoResult<Response> {
    let bytes = recv_bytes(stream)?;
    if bytes.is_empty() {
        return Err(ProtoError { message: "Got an empty payload".to_string() });
    }
    let cursor = std::io::Cursor::new(bytes.clone());
    match ciborium::from_reader::<Response, _>(cursor) {
        Ok(msg) => {
            crate::log_debug!("pueue_lib::network::protocol", "pueue_lib/src/network/protocol.rs:199", "Received message: {:#?}", msg);
            Ok(msg)
        }
        Err(e) => {
            // Try as Value
            let cursor2 = std::io::Cursor::new(bytes.clone());
            if let Ok(value) = ciborium::from_reader::<ciborium::value::Value, _>(cursor2) {
                Err(ProtoError { message: format!("Got unexpected but valid message. Are you up-to-date?:\n{:#?}", value) })
            } else {
                Err(ProtoError { message: format!("Couldn't deserialize message:\n{}", e) })
            }
        }
    }
}

// Helper used by commands that expect a Status message etc.
pub fn receive_with_location(stream: &mut BoxTransport, location: &'static str) -> Result<Response> {
    receive_response(stream).map_err(|e| e.to_report(location))
}
