use crate::error::{Report, Result};
use crate::protocol::{recv_bytes, BoxTransport, ProtoError, PROTOCOL_VERSION};
use crate::settings::Settings;
use std::io::Write;
use std::os::unix::net::UnixStream;

pub struct Client {
    pub stream: BoxTransport,
    pub settings: Settings,
}

// Certificate parsing mimicking rustls pem parsing
pub fn load_certificate(path: &std::path::Path) -> std::result::Result<Vec<u8>, Report> {
    // returns DER bytes of first CERTIFICATE pem item (or empty)
    let content = std::fs::read(path).map_err(|e| {
        let msg = format!("Invalid or malformed certificate: Failed to parse daemon certificate:\n{}", io_debug(&e));
        Report::new(msg, "pueue/src/bin/pueue.rs:90")
    })?;
    parse_pem_certificate(&content).map_err(|msg| {
        Report::new(format!("Invalid or malformed certificate: Failed to parse daemon certificate:\n{}", msg), "pueue/src/bin/pueue.rs:90")
    })
}

fn io_debug(e: &std::io::Error) -> String {
    // Format like Io(Os { code: 2, kind: NotFound, message: "No such file or directory" })
    if let Some(code) = e.raw_os_error() {
        format!("Io(Os {{ code: {}, kind: {:?}, message: \"{}\" }})", code, e.kind(), error_message_only(e))
    } else {
        format!("Io({:?})", e)
    }
}
fn error_message_only(e: &std::io::Error) -> String {
    // std io error Display includes " (os error N)" suffix; rust debug message is without suffix
    let s = format!("{}", e);
    if let Some(idx) = s.rfind(" (os error") {
        s[..idx].to_string()
    } else { s }
}

pub fn parse_pem_certificate(content: &[u8]) -> std::result::Result<Vec<u8>, String> {
    let text = String::from_utf8_lossy(content);
    // Find BEGIN CERTIFICATE
    let begin_marker = "-----BEGIN CERTIFICATE-----";
    let end_marker = "-----END CERTIFICATE-----";
    if let Some(start) = text.find(begin_marker) {
        let rest = &text[start + begin_marker.len()..];
        if let Some(end) = rest.find(end_marker) {
            let inner = &rest[..end];
            let b64: String = inner.chars().filter(|c| !c.is_whitespace()).collect();
            // base64 decode
            return decode_base64(&b64).map_err(|e| format!("Base64Decode(\"{}\")", e));
        } else {
            // incomplete section? rustls pem parser would return error? Treat as NoItems?
            return Err("NoItemsFound".to_string());
        }
    }
    Err("NoItemsFound".to_string())
}

fn decode_base64(s: &str) -> std::result::Result<Vec<u8>, String> {
    // Validate characters
    let mut vals = Vec::new();
    for (i, ch) in s.chars().enumerate() {
        if ch == '=' { break; }
        let v = match ch {
            'A'..='Z' => ch as u32 - 'A' as u32,
            'a'..='z' => ch as u32 - 'a' as u32 + 26,
            '0'..='9' => ch as u32 - '0' as u32 + 52,
            '+' => 62,
            '/' => 63,
            _ => {
