impl Client {
    pub fn new(settings: Settings, secret: Vec<u8>, cert_der: Option<Vec<u8>>, cert_path: Option<std::path::PathBuf>) -> Result<Self> {
        let shared = settings.shared();
        let mut stream: BoxTransport = if shared.use_unix_socket {
            let socket_path = shared.unix_socket_path();
            match UnixStream::connect(&socket_path) {
                Ok(s) => Box::new(s),
                Err(e) => {
                    return Err(Report::chain(vec![
                        "Failed to initialize client.".to_string(),
                        "Failed to initialize stream.".to_string(),
                        format!("I/O error at path {:?} while connecting to daemon. Did you start it?:\n{}", socket_path.to_string_lossy(), e),
                    ], "/workspace/pueue_lib/src/network/client.rs:85"));
                }
            }
        } else {
            // TCP
            let addr_str = format!("{}:{}", shared.host, shared.port);
            // Resolve/connect using std
            let tcp = connect_tcp(&shared.host, &shared.port).map_err(|_| {
                Report::chain(vec![
                    "Failed to initialize client.".to_string(),
                    "Failed to initialize stream.".to_string(),
                    format!("Failed to connect to the daemon on {}. Did you start it?", addr_str),
                ], "/workspace/pueue_lib/src/network/client.rs:85")
            })?;
            // TLS via openssl s_client bridge. Close probe tcp (openssl will make its own connection)
            drop(tcp);
            let cert_path = cert_path.unwrap_or_else(|| shared.daemon_cert_path());
            let transport = crate::protocol::TlsTransport::new(&shared.host, &shared.port, &cert_path);
            match transport {
                Ok(t) => Box::new(t) as BoxTransport,
                Err(msg) => {
                    return Err(Report::chain(vec![
                        "Failed to initialize client.".to_string(),
                        "Failed to initialize stream.".to_string(),
                        format!("Failed to initialize tls:\n{}", msg),
                    ], "/workspace/pueue_lib/src/network/client.rs:85"));
                }
            }
        };

        // Handshake: send secret
        // If sending fails, original wraps? We'll map as failed initialize client with receive version type? Actually send is in Client::new before version receive.
        // Use bytes framing.
        let send_err = crate::protocol::send_bytes(&mut stream, &secret);
        if let Err(e) = send_err {
            // Guess: treat as Daemon went away? Need observable later; map to generic chain with Failed to initialize client.
            return Err(Report::chain(vec![
                "Failed to initialize client.".to_string(),
                e.message.clone(),
            ], "/workspace/pueue_lib/src/network/client.rs:97"));
        }

        // Receive version
        let version_bytes = match recv_bytes(&mut stream) {
            Ok(b) => b,
            Err(e) => {
                return Err(Report::chain(vec![
                    "Failed to initialize client.".to_string(),
                    "Failed to receive version during handshake with daemon.".to_string(),
                    e.message.clone(),
                ], "/workspace/pueue_lib/src/network/client.rs:97"));
            }
        };
        if version_bytes.is_empty() {
            return Err(Report::chain(vec![
                "Failed to initialize client.".to_string(),
                "Daemon went away after sending secret. Did you use the correct secret?".to_string(),
            ], "/workspace/pueue_lib/src/network/client.rs:99"));
        }
        let version = match String::from_utf8(version_bytes) {
            Ok(v) => v,
            Err(_) => {
                return Err(Report::chain(vec![
                    "Failed to initialize client.".to_string(),
                    "Daemon sent invalid UTF-8. Did you use the correct secret?".to_string(),
                ], "/workspace/pueue_lib/src/network/client.rs:104"));
            }
        };
        if version != PROTOCOL_VERSION {
            crate::log_warn!("pueue_lib::network::client", "pueue_lib/src/network/client.rs:111", "Different protocol version detected '{}'. Consider updating and restarting the daemon.", version);
        }
        Ok(Self { stream, settings })
    }

    pub fn send(&mut self, request: &crate::message::Request) -> std::result::Result<(), ProtoError> {
        crate::protocol::send_request(&mut self.stream, request)
    }
    pub fn receive(&mut self) -> std::result::Result<crate::message::Response, ProtoError> {
        crate::protocol::receive_response(&mut self.stream)
    }
    pub fn send_and_receive(&mut self, request: &crate::message::Request, location: &'static str) -> Result<crate::message::Response> {
        self.send(request).map_err(|e| e.to_report(location))?;
        self.receive().map_err(|e| e.to_report(location))
    }
}

fn connect_tcp(host: &str, port: &str) -> std::io::Result<std::net::TcpStream> {
    // Use to_socket_addrs
    use std::net::ToSocketAddrs;
    let addr = format!("{}:{}", host, port);
    let mut addrs = addr.to_socket_addrs()?;
    if let Some(a) = addrs.next() {
        std::net::TcpStream::connect(a)
    } else {
        Err(std::io::Error::new(std::io::ErrorKind::NotFound, "no address"))
    }
}
