impl TlsTransport {
    pub fn new(host: &str, port: &str, cert_path: &std::path::Path) -> std::result::Result<Self, String> {
        // Spawn openssl s_client as TLS bridge.
        // We attempt to detect early handshake failure by waiting briefly and checking exit.
        let mut cmd = std::process::Command::new("openssl");
        cmd.arg("s_client")
            .arg("-quiet")
            .arg("-connect")
            .arg(format!("{}:{}", host, port))
            .arg("-CAfile")
            .arg(cert_path)
            .arg("-servername")
            .arg(host)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null());
        let mut child = cmd.spawn().map_err(|e| format!("{}.", e))?;
        // Give handshake a moment; if process exited, treat as tls error.
        std::thread::sleep(std::time::Duration::from_millis(150));
        match child.try_wait() {
            Ok(Some(_status)) => {
                return Err("Connection reset by peer (os error 104).".to_string());
            }
            Ok(None) => {}
            Err(e) => return Err(format!("{}.", e)),
        }
        let stdin = child.stdin.take();
        let stdout = child.stdout.take();
        Ok(Self { child, stdin, stdout })
    }
}
