use chrono::{DateTime, Datelike, Duration, Local, NaiveDate, NaiveDateTime, NaiveTime, TimeZone, Timelike, Weekday};

pub fn parse_delay(input: &str) -> std::result::Result<DateTime<Local>, String> {
    parse_date_string(input).ok_or_else(|| "could not parse as seconds or date expression".to_string())
}

pub fn parse_date_string(input: &str) -> Option<DateTime<Local>> {
    let now = Local::now();
    let s_raw = input.trim();
    if s_raw.is_empty() { return None; }
    // integer seconds (signed)
    if let Ok(secs) = s_raw.parse::<i64>() {
        return Some(now + Duration::seconds(secs));
    }
    let s = s_raw.to_string();
    // Try RFC3339 / known absolute patterns
    if let Some(dt) = parse_absolute(&s, now) {
        return Some(dt);
    }
    // Relative / natural expressions
    parse_natural(&s, now)
}

fn local_from_naive(ndt: NaiveDateTime) -> Option<DateTime<Local>> {
    Local.from_local_datetime(&ndt).single().or_else(|| Local.from_local_datetime(&ndt).earliest())
}

fn parse_absolute(s: &str, now: DateTime<Local>) -> Option<DateTime<Local>> {
    // RFC3339
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Some(dt.with_timezone(&Local));
    }
    // Try formats
    let fmts = [
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%Y-%m-%d %I:%M%p",
        "%Y-%m-%d %I%p",
        "%Y-%m-%d %H:%M:%S%.f",
    ];
    for fmt in fmts {
        if let Ok(ndt) = NaiveDateTime::parse_from_str(s, fmt) {
            return local_from_naive(ndt);
        }
        if let Ok(nd) = NaiveDate::parse_from_str(s, fmt) {
            return local_from_naive(nd.and_hms_opt(0, 0, 0)?);
        }
    }
    // Fix single-digit variants by trying normalized: interim accepts no leading zeros; chrono formats above also accept them.
    None
}

fn parse_time_str(s: &str, base_date: NaiveDate) -> Option<NaiveDateTime> {
    // 5pm, 5:30pm, 18:30, 10.5, 24:00, 25:00 (overflow handled by caller)
    let st = s.trim().to_lowercase().replace(' ', "");
    // 10.5 -> 10:05 interpretation observed
    if st.contains('.') && !st.contains(':') {
        let parts: Vec<&str> = st.split('.').collect();
        if parts.len() == 2 && parts.iter().all(|p| p.chars().all(|c| c.is_ascii_digit())) {
            // interim seems to parse 10.5 as 10:05
            if let (Ok(h), Ok(m)) = (parts[0].parse::<u32>(), parts[1].parse::<u32>()) {
                return make_time_overflow(base_date, h, m * 5, 0); // Wait 10.5 => 10:05, not 10:25. See logic below overridden
            }
        }
    }
    let (ampm, core) = if st.ends_with("am") {
        (Some(false), &st[..st.len() - 2])
    } else if st.ends_with("pm") {
        (Some(true), &st[..st.len() - 2])
    } else {
        (None, st.as_str())
    };
    let parts: Vec<&str> = core.split(':').collect();
    if parts.is_empty() || parts.len() > 3 { return None; }
    if !parts.iter().all(|p| !p.is_empty() && p.chars().all(|c| c.is_ascii_digit())) { return None; }
    let mut h: u32 = parts[0].parse().ok()?;
    let m: u32 = if parts.len() >= 2 { parts[1].parse().ok()? } else { 0 };
    let sec: u32 = if parts.len() == 3 { parts[2].parse().ok()? } else { 0 };
    if let Some(is_pm) = ampm {
        if h == 12 { h = if is_pm { 12 } else { 0 }; }
        else if is_pm { h += 12; }
    }
    make_time_overflow(base_date, h, m, sec)
}

fn make_time_overflow(base_date: NaiveDate, h: u32, m: u32, sec: u32) -> Option<NaiveDateTime> {
    // handle h>=24 etc by adding days
    let total_seconds = h as i64 * 3600 + m as i64 * 60 + sec as i64;
    let days = total_seconds.div_euclid(86400);
    let secs_of_day = total_seconds.rem_euclid(86400);
    let date = base_date + Duration::days(days);
    let time = NaiveTime::from_num_seconds_from_midnight_opt(secs_of_day as u32, 0)?;
    Some(NaiveDateTime::new(date, time))
}

fn month_from_name(name: &str) -> Option<u32> {
    match name.to_lowercase().as_str() {
        "january" | "jan" => Some(1),
        "february" | "feb" => Some(2),
        "march" | "mar" => Some(3),
        "april" | "apr" => Some(4),
        "may" => Some(5),
        "june" | "jun" => Some(6),
        "july" | "jul" => Some(7),
        "august" | "aug" => Some(8),
        "september" | "sep" | "sept" => Some(9),
        "october" | "oct" => Some(10),
        "november" | "nov" => Some(11),
        "december" | "dec" => Some(12),
        _ => None,
    }
}

fn weekday_from_name(name: &str) -> Option<Weekday> {
    match name.to_lowercase().as_str() {
        "monday" | "mon" => Some(Weekday::Mon),
        "tuesday" | "tue" | "tues" => Some(Weekday::Tue),
        "wednesday" | "wed" => Some(Weekday::Wed),
        "thursday" | "thu" | "thur" | "thurs" => Some(Weekday::Thu),
        "friday" | "fri" => Some(Weekday::Fri),
        "saturday" | "sat" => Some(Weekday::Sat),
        "sunday" | "sun" => Some(Weekday::Sun),
        _ => None,
    }
}

fn add_months(date: NaiveDate, months: i64, time: NaiveTime) -> Option<NaiveDateTime> {
    let total = (date.year() as i64) * 12 + (date.month() as i64 - 1) + months;
    let year = total.div_euclid(12) as i32;
    let month = total.rem_euclid(12) as u32 + 1;
    // clamp day
    let mut day = date.day();
    loop {
        if let Some(d) = NaiveDate::from_ymd_opt(year, month, day) {
            return Some(NaiveDateTime::new(d, time));
        }
        day -= 1;
        if day == 0 { return None; }
    }
}

fn parse_natural(s: &str, now: DateTime<Local>) -> Option<DateTime<Local>> {
    let lower = s.to_lowercase();
    let tokens: Vec<String> = lower.split_whitespace().map(|t| t.to_string()).collect();
    if tokens.is_empty() { return None; }

    // special words
    if tokens.len() == 1 {
        match tokens[0].as_str() {
            "now" => return Some(now),
            "today" => return Some(now), // observed returns current time with nanos
            "tomorrow" => return Some(now + Duration::days(1)), // observed keeps current time
            "yesterday" => return Some(now - Duration::days(1)),
            _ => {}
        }
    }

    // time only, e.g. 18:30, 5pm, 10.5 (special 10.5 handling)
    if tokens.len() == 1 {
        // 10.5 special: parse as HH:MM where fractional part is minutes?? 10.5 -> 10:05
        let t = &tokens[0];
        // duration like 3600s, 3h, 90m, 1d, 1w
        if let Some(dt) = parse_duration_token(t, now) {
            return Some(dt);
        }
        if let Some(ndt) = parse_time_token_special(t, now.date_naive()) {
            return local_from_naive(ndt);
        }
        // weekday alone
        if let Some(wd) = weekday_from_name(t) {
            let date = next_weekday(now.date_naive(), wd, false);
            return local_from_naive(NaiveDateTime::new(date, NaiveTime::from_hms_opt(0, 0, 0)?));
        }
        // date like 4/1 (M/D), maybe year?
        if let Some(dt) = parse_slash_date(t, now) {
            return Some(dt);
        }
    }

    // duration sequences like "5 minutes", "4 months", "1 week", "5 minutes ago", "1 month", "1 year"
    if let Some(dt) = parse_relative_phrase(&tokens, now) {
        return Some(dt);
    }

    // "1d 03:00" or "1days xxx"? First token duration, rest time
    // Detect first token as duration token and remainder as time/date
    if tokens.len() >= 2 {
        if let Some(base) = parse_duration_token(&tokens[0], now) {
            let rest = tokens[1..].join(" ");
            if let Some(ndt) = parse_time_token_special(&rest.replace(' ', ""), base.date_naive()) {
                // If time specified, time of day replaced, date from base (1d from now = tomorrow date)
                return local_from_naive(ndt);
            }
        }
    }

    // weekday with time: "wednesday 10:30pm", "next friday"
    {
        let mut idx = 0usize;
        let mut next_modifier = false;
        if tokens.get(0).map(|x| x.as_str()) == Some("next") {
            next_modifier = true;
            idx = 1;
        }
        if let Some(wdname) = tokens.get(idx) {
            if let Some(wd) = weekday_from_name(wdname) {
                // "next friday" observed: 2026-09-30 Wed, next friday = 2026-10-02 (closest Friday), not following week.
                let date = next_weekday(now.date_naive(), wd, false);
                let _ = next_modifier;
                if tokens.len() == idx + 1 {
                    return local_from_naive(NaiveDateTime::new(date, NaiveTime::from_hms_opt(0, 0, 0)?));
                } else if tokens.len() == idx + 2 {
                    if let Some(ndt) = parse_time_token_special(&tokens[idx + 1], date) {
                        return local_from_naive(ndt);
                    }
                    return None;
                }
            }
        }
    }

    // Month name dates: April 1 2020 18:30:00, 1 Apr 8:30pm, Sep 30 (2026 invalid observed Sep 30 2026 INVALID? That test maybe due token grammar)
    if let Some(dt) = parse_month_date(&tokens, now) {
        return Some(dt);
    }

    // Slash date with time
    // YYYY-M-D time forms were handled by absolute with normalization? try tokens join for date+time
    if let Some(dt) = parse_date_plus_time_tokens(&tokens, now) {
        return Some(dt);
    }

    None
}

fn next_weekday(from: NaiveDate, wd: Weekday, _strict_next_week: bool) -> NaiveDate {
    // Closest weekday in future. If today is that weekday, interim chooses ? assume next occurrence (7 days?) Need check.
    let cur = from.weekday();
    let mut diff = (wd.num_days_from_monday() as i64 - cur.num_days_from_monday() as i64).rem_euclid(7);
    if diff == 0 { diff = 7; }
    from + Duration::days(diff)
}

fn parse_duration_token(t: &str, now: DateTime<Local>) -> Option<DateTime<Local>> {
    // e.g. 3600s, 3h, 90m, 1d, 1w, 1days, 1day
    let t = t.trim();
    // find numeric prefix
    let mut split = 0usize;
    for (i, ch) in t.char_indices() {
        if ch.is_ascii_digit() { split = i + ch.len_utf8(); } else { break; }
    }
    if split == 0 { return None; }
    let (num_s, unit) = t.split_at(split);
    if unit.is_empty() { return None; }
    let n: i64 = num_s.parse().ok()?;
    apply_duration(now, n, unit)
}

fn apply_duration(now: DateTime<Local>, n: i64, unit: &str) -> Option<DateTime<Local>> {
    match unit {
        "s" | "sec" | "secs" | "second" | "seconds" => Some(now + Duration::seconds(n)),
        "m" | "min" | "mins" | "minute" | "minutes" => Some(now + Duration::minutes(n)),
        "h" | "hour" | "hours" => Some(now + Duration::hours(n)),
        "d" | "day" | "days" => Some(now + Duration::days(n)),
        "w" | "week" | "weeks" => Some(now + Duration::weeks(n)),
        "month" | "months" => {
            // months from today at 00:00:00 if it was phrase? For token like 1month? Help says 4 months => at 00:00.
            // We'll be handled at phrase level; here keep time
            let ndt = add_months(now.date_naive(), n, now.time())?;
            local_from_naive(ndt)
        }
        "y" | "year" | "years" => {
            let ndt = add_months(now.date_naive(), n * 12, now.time())?;
            local_from_naive(ndt)
        }
        _ => None,
    }
}

fn parse_relative_phrase(tokens: &[String], now: DateTime<Local>) -> Option<DateTime<Local>> {
    // ago handling
    let mut ago = false;
    let mut toks: Vec<String> = tokens.to_vec();
    if toks.last().map(|x| x.as_str()) == Some("ago") {
        ago = true;
        toks.pop();
    }
    if toks.len() == 2 {
        if let Ok(n) = toks[0].parse::<i64>() {
            let unit = toks[1].as_str();
            let signed = if ago { -n } else { n };
