        .about("Display the current status of all tasks")
        .arg(Arg::new("query").help("Users can specify a custom query to filter for specific values, order by a column or limit the amount of tasks listed. Use `--help` for the full syntax definition").long_help("Users can specify a custom query to filter for specific values, order by a column\nor limit the amount of tasks listed.\n\nSyntax:\n   [column_selection]? [filter]* [order_by]? [limit]?\n\nwhere:\n  - column_selection := `columns=[column]([column],)*`\n  - column := `id | status | command | label | path | enqueue_at | dependencies | start |\n  end`\n  - filter := `[filter_column] [filter_op] [filter_value]`\n    (note: not all columns support all operators, see \"Filter columns\" below.)\n  - filter_column := `status | command | label | start | end | enqueue_at`\n  - filter_op := `= | != | < | > | %=`\n    (`%=` means 'contains', as in the test value is a substring of the column value)\n  - order_by := `order_by [column] [order_direction]`\n  - order_direction := `asc | desc`\n  - limit := `[limit_type]? [limit_count]`\n  - limit_type := `first | last`\n  - limit_count := a positive integer\n\nFilter columns:\n  - `status` supports the operators `=`, `!=`\n    against test values that are:\n      - strings like `queued`, `stashed`, `paused`, `running`, `success`, `failed`\n  - `command`, `label` support the operators `=`, `!=`, `%=`\n    against test values that are:\n      - strings like `some text`\n  - `start`, `end`, `enqueue_at` contain a datetime\n    which support the operators `=`, `!=`, `<`, `>`\n    against test values that are:\n      - date like `YYYY-MM-DD`\n      - time like `HH:mm:ss` or `HH:mm`\n      - datetime like `YYYY-MM-DDHH:mm:ss`\n        (note there is currently no separator between the date and the time)\n\nExamples:\n  - `status=running`\n  - `command%=echo`\n  - `label=mytask`\n  - `columns=id,status,command status=running start > 2023-05-2112:03:17 order_by command\n  first 5`\n\nThe formal syntax is defined here:\nhttps://github.com/Nukesor/pueue/blob/main/pueue/src/client/commands/state/query/syntax.pest\n\nMore documentation is on the query syntax PR:\nhttps://github.com/Nukesor/pueue/issues/350#issue-1359083118").num_args(0..).value_name("QUERY"))
        .arg(Arg::new("json").short('j').long("json").help("Print the current state as json to stdout. This does not include the output of tasks. Use `log -j` if you want everything").action(ArgAction::SetTrue))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Only show tasks of a specific group"))
}

fn log_command() -> Command {
    Command::new("log")
        .about("Display the log output of finished tasks")
        .long_about("Display the log output of finished tasks.\n\nOnly the last few lines will be shown by default. If you want to follow the output of a task, please use the \"follow\" subcommand.")
        .arg(Arg::new("task_ids").help("View the task output of these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("View the outputs of this specific group's tasks"))
        .arg(Arg::new("all").short('a').long("all").help("Show the logs of all groups' tasks").action(ArgAction::SetTrue))
        .arg(Arg::new("json").short('j').long("json").help("Print the resulting tasks and output as json").long_help("Print the resulting tasks and output as json.\n\nBy default only the last lines will be returned unless --full is provided. Take care, as the json cannot be streamed! If your logs are really huge, using --full can use all of your machine's RAM.").action(ArgAction::SetTrue))
        .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of each task's output").long_help("Only print the last X lines of each task's output.\n\nThis is done by default if you're looking at multiple tasks.").value_parser(value_parser!(usize)).conflicts_with("full"))
        .arg(Arg::new("full").short('f').long("full").help("Show the whole output").action(ArgAction::SetTrue))
}

fn follow_command() -> Command {
    Command::new("follow")
        .about("Follow the output of a currently running task. This command works like \"tail -f\"")
        .arg(Arg::new("task_id").help("The id of the task you want to watch").long_help("The id of the task you want to watch.\n\nIf no or multiple tasks are running, you have to specify the id. If only a single task is running, you can omit the id.").value_name("TASK_ID").value_parser(value_parser!(usize)))
        .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of the output before following").value_parser(value_parser!(usize)))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaitStatus {
    Queued,
    Running,
    Done,
    Success,
}
pub fn parse_wait_status(s: &str) -> std::result::Result<WaitStatus, String> {
    match s {
        "Queued" | "queued" => Ok(WaitStatus::Queued),
        "Running" | "running" => Ok(WaitStatus::Running),
        "Done" | "done" => Ok(WaitStatus::Done),
        "Success" | "success" => Ok(WaitStatus::Success),
        _ => Err("Matching variant not found".to_string()),
    }
}

fn wait_command() -> Command {
    Command::new("wait")
        .about("Wait until tasks are finished")
        .long_about("Wait until tasks are finished.\n\nBy default, this will wait for all tasks in the default group to finish.\n\nNote: This will also wait for all tasks that aren't somehow 'Done'. Includes: [Paused, Stashed, Locked, Queued, ...]")
        .arg(Arg::new("task_ids").help("This allows you to wait for specific tasks to finish").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Wait for all tasks in a specific group").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Wait for all tasks across all groups and the default group").action(ArgAction::SetTrue))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Don't show any log output while waiting").action(ArgAction::SetTrue))
        .arg(Arg::new("status").short('s').long("status").value_name("STATUS").help("Wait for tasks to reach a specific task status").value_parser(parse_wait_status))
}

fn clean_command() -> Command {
    Command::new("clean")
        .about("Remove all finished tasks from the list")
        .arg(Arg::new("successful_only").short('s').long("successful-only").help("Only clean tasks that finished successfully").action(ArgAction::SetTrue))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Only clean tasks of a specific group"))
}

fn reset_command() -> Command {
    Command::new("reset")
        .about("Kill all tasks, clean up afterwards and reset EVERYTHING!")
        .arg(Arg::new("groups").short('g').long("groups").value_name("GROUPS").help("If groups are specified, only those specific groups will be reset"))
        .arg(Arg::new("force").short('f').long("force").help("Don't ask for any confirmation").action(ArgAction::SetTrue))
}

fn shutdown_command() -> Command {
    Command::new("shutdown")
        .about("Remotely shut down the daemon. Should only be used if the daemon isn't started by a service manager")
}

fn parallel_command() -> Command {
    Command::new("parallel")
        .about("Set the amount of allowed parallel tasks")
        .long_about("Set the amount of allowed parallel tasks\n\nBy default, adjusts the amount of the default group.\n\nNo tasks will be stopped, if this is lowered. This limit is only considered when tasks are scheduled.")
        .arg(Arg::new("parallel_tasks").help("The amount of allowed parallel tasks").long_help("The amount of allowed parallel tasks.\n\nSetting this to 0 means an unlimited amount of parallel tasks.").value_name("PARALLEL_TASKS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("group").help("Set the amount for a specific group"))
}

fn completions_command() -> Command {
    Command::new("completions")
        .about("Generates shell completion files")
        .long_about("Generates shell completion files.\n\nThis can be ignored during normal operations.")
        .arg(Arg::new("shell").help("The target shell").required(true).value_name("SHELL").value_parser(["bash", "elvish", "fish", "power-shell", "zsh", "nushell"]))
        .arg(Arg::new("output_directory").help("The output directory to which the file should be written").value_name("OUTPUT_DIRECTORY"))
}
