use crate::message::{Signal};
use clap::{Arg, ArgAction, Command, value_parser};

pub fn build_cli() -> Command {
    let cmd = Command::new("pueue")
        .version("4.0.4")
        .color(clap::ColorChoice::Never)
        .about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Verbose mode (-v, -vv, -vvv)")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("color")
                .long("color")
                .value_name("COLOR")
                .help("Colorize the output; auto enables color output when connected to a tty")
                .value_parser(["auto", "never", "always"])
                .default_value("auto"),
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("CONFIG")
                .help("If provided, Pueue only uses this config file")
                .long_help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The commandline option overwrites the environment variable!"),
        )
        .arg(
            Arg::new("profile")
                .short('p')
                .long("profile")
                .value_name("PROFILE")
                .help("The name of the profile that should be loaded from your config file"),
        );

    let cmd = cmd.subcommand(add_command());
    let cmd = cmd.subcommand(remove_command());
    let cmd = cmd.subcommand(switch_command());
    let cmd = cmd.subcommand(stash_command());
    let cmd = cmd.subcommand(enqueue_command());
    let cmd = cmd.subcommand(start_command());
    let cmd = cmd.subcommand(restart_command());
    let cmd = cmd.subcommand(pause_command());
    let cmd = cmd.subcommand(kill_command());
    let cmd = cmd.subcommand(send_command());
    let cmd = cmd.subcommand(edit_command());
    let cmd = cmd.subcommand(env_command());
    let cmd = cmd.subcommand(group_command());
    let cmd = cmd.subcommand(status_command());
    let cmd = cmd.subcommand(log_command());
    let cmd = cmd.subcommand(follow_command());
    let cmd = cmd.subcommand(wait_command());
    let cmd = cmd.subcommand(clean_command());
    let cmd = cmd.subcommand(reset_command());
    let cmd = cmd.subcommand(shutdown_command());
    let cmd = cmd.subcommand(parallel_command());
    let cmd = cmd.subcommand(completions_command());
    cmd
}

fn delay_arg(short: bool) -> Arg {
