        .value_name("delay")
        .help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted formats")
        .value_parser(crate::date_parse::parse_delay);
    if short { // for stash/enqueue help text differs in summary? stash long same, short says Delay enqueuing...
        // We'll customize per command below via overrides
    }
    a.long("delay").short('d')
}

fn add_command() -> Command {
    Command::new("add")
        .about("Enqueue a task for execution")
        .long_about("Enqueue a task for execution.\n\nThere're many different options when scheduling a task. Check the individual option help texts for more information. Furthermore, please remember that scheduled commands are executed via your system shell. This means that the command needs proper shell escaping. The safest way to preserve shell escaping is to surround your command with quotes, for example:\n\npueue add 'ls $HOME && echo \"Some string\"'")
        .arg(Arg::new("command").help("The command to be added").required(true).num_args(1..).value_name("COMMAND"))
        .arg(Arg::new("working_directory").short('w').long("working-directory").value_name("working-directory").help("Specify current working directory"))
        .arg(Arg::new("escape").short('e').long("escape").help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\").").action(ArgAction::SetTrue))
        .arg(Arg::new("immediate").short('i').long("immediate").help("Immediately start the task").action(ArgAction::SetTrue).conflicts_with_all(["stashed", "delay"]))
        .arg(Arg::new("follow").long("follow").help("Immediately follow a task, if it's started with --immediate").action(ArgAction::SetTrue).requires("immediate"))
        .arg(Arg::new("stashed").short('s').long("stashed").help("Create the task in Stashed state").long_help("Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty.").action(ArgAction::SetTrue))
        .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted formats").value_parser(crate::date_parse::parse_delay))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Assign the task to a group").long_help("Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the amount of parallel tasks for each group. If no group is specified, the default group will be used.\n\nCreate groups via the `pueue group` subcommand"))
        .arg(Arg::new("after").short('a').long("after").value_name("after").help("Start the task once all specified tasks have successfully finished").long_help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well.").num_args(1..).value_parser(value_parser!(usize)))
        .arg(Arg::new("priority").short('o').long("priority").value_name("PRIORITY").help("Start this task with a higher priority").long_help("Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed.").value_parser(value_parser!(i32)))
        .arg(Arg::new("label").short('l').long("label").value_name("LABEL").help("Add some information for yourself").long_help("Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to it."))
        .arg(Arg::new("print_task_id").short('p').long("print-task-id").help("Only return the task id instead of a text").long_help("Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts.").action(ArgAction::SetTrue))
}

fn remove_command() -> Command {
    Command::new("remove")
        .about("Remove tasks from the list. Running or paused tasks need to be killed first")
        .arg(Arg::new("task_ids").help("The task ids to be removed").required(true).num_args(1..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
}

fn switch_command() -> Command {
    Command::new("switch")
        .about("Switches the queue position of two commands")
        .long_about("Switches the queue position of two commands.\n\nOnly works on queued and stashed commands.")
        .arg(Arg::new("task_id_1").help("The first task id").required(true).value_name("TASK_ID_1").value_parser(value_parser!(usize)))
        .arg(Arg::new("task_id_2").help("The second task id").required(true).value_name("TASK_ID_2").value_parser(value_parser!(usize)))
}

const DELAY_FORMAT_LONG: &str = "\n\nDELAY FORMAT:\n\n    The --delay argument must be either a number of seconds or a \"date expression\" similar to GNU\n    \"date -d\" with some extensions. It does not attempt to parse all natural language, but is\n    incredibly flexible. Here are some supported examples.\n\n    2020-04-01T18:30:00   // RFC 3339 timestamp\n    2020-4-1 18:2:30      // Optional leading zeros\n    2020-4-1 5:30pm       // Informal am/pm time\n    2020-4-1 5pm          // Optional minutes and seconds\n    April 1 2020 18:30:00 // English months\n    1 Apr 8:30pm          // Implies current year\n    4/1                   // American form date\n    wednesday 10:30pm     // The closest wednesday in the future at 22:30\n    wednesday             // The closest wednesday in the future\n    4 months              // 4 months from today at 00:00:00\n    1 week                // 1 week at the current time\n    1days                 // 1 day from today at the current time\n    1d 03:00              // The closest 3:00 after 1 day (24 hours)\n    3h                    // 3 hours from now\n    3600s                 // 3600 seconds from now";

fn stash_command() -> Command {
    Command::new("stash")
        .about("Stash a task. Stashed tasks won't be automatically started")
        .long_about("Stash a task. Stashed tasks won't be automatically started.\n\nThe enqueue an item, use the `pueue enqueue` subcommand. Stashed entries can also be explicitely started via `pueue start $task_id`.")
        .arg(Arg::new("task_ids").help("Stash these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Stash all queued tasks in a group").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Stash all queued tasks across all groups").action(ArgAction::SetTrue))
        .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below").long_help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below").value_parser(crate::date_parse::parse_delay))
        // Note: stash help long doesn't include DELAY FORMAT section (checking). Enqueue does.
}

fn enqueue_command() -> Command {
    let long_about = format!("Enqueue stashed tasks. They'll be handled normally afterwards.\n\nEnqueues all stashed task in the default group if no arguments are given.{}", DELAY_FORMAT_LONG);
    Command::new("enqueue")
        .about("Enqueue stashed tasks. They'll be handled normally afterwards")
        .long_about(long_about)
        .arg(Arg::new("task_ids").help("Enqueue these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Enqueue all stashed tasks in a group").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Enqueue all stashed tasks across all groups").action(ArgAction::SetTrue))
        .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below").value_parser(crate::date_parse::parse_delay))
}

fn start_command() -> Command {
    Command::new("start")
        .about("Resume operation of specific tasks or groups of tasks")
        .long_about("Resume operation of specific tasks or groups of tasks.\n\nWithout any parameters this resumes the default group and all its tasks. Can also be used force-start specific tasks, which **ignores** any group parallelism limits or dependencies a task my have!")
        .arg(Arg::new("task_ids").help("Start these specific tasks. Paused tasks will resumed. Queued/Stashed tasks will be force-started").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Resume a specific group and all paused tasks in it").long_help("Resume a specific group and all paused tasks in it.\n\nThe group will be set to running and its paused tasks will be resumed.").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Resume all groups!").long_help("Resume all groups!\n\nAll groups will be set to running and paused tasks will be resumed.").action(ArgAction::SetTrue))
}

fn restart_command() -> Command {
    Command::new("restart")
        .about("Restart failed or successful task(s)")
        .long_about("Restart failed or successful task(s).\n\nBy default, identical tasks will be created and enqueued, but it's possible to restart in-place. You can also edit a few properties, such as the path and the command, before restarting.")
        .arg(Arg::new("task_ids").help("Restart these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("all_failed").short('a').long("all-failed").help("Restart all failed tasks across all groups").long_help("Restart all failed tasks across all groups.\n\nThis is nice for usage in combination with `-i/--in-place` (or the respective config option).").action(ArgAction::SetTrue).conflicts_with("failed_in_group"))
        .arg(Arg::new("failed_in_group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP").help("Like `--all-failed`, but only restart tasks failed tasks of a specific group"))
        .arg(Arg::new("immediate").short('k').long("immediate").help("Immediately start the tasks, no matter how many open slots there are. This will ignore any dependencies tasks may have").action(ArgAction::SetTrue))
        .arg(Arg::new("stashed").short('s').long("stashed").help("Set the restarted task to a \"Stashed\" state. Useful to avoid immediate execution").action(ArgAction::SetTrue).conflicts_with("immediate"))
        .arg(Arg::new("in_place").short('i').long("in-place").help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks").long_help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks.\n\nThis can also be enabled by default via the `restart_in_place` config option.").action(ArgAction::SetTrue))
        .arg(Arg::new("not_in_place").long("not-in-place").help("Restart the task by creating a new identical tasks. Only necessary if you have the `restart_in_place` configuration set to true").action(ArgAction::SetTrue))
        .arg(Arg::new("edit").short('e').long("edit").help("Edit the task before restarting").action(ArgAction::SetTrue))
}

fn pause_command() -> Command {
    Command::new("pause")
        .about("Either pause running tasks or specific groups of tasks")
        .long_about("Either pause running tasks or specific groups of tasks.\n\nBy default, pauses the default group and all its tasks. A paused queue (group) won't start any new tasks.")
        .arg(Arg::new("task_ids").help("Pause these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Pause a specific group").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Pause all groups!").action(ArgAction::SetTrue))
        .arg(Arg::new("wait").short('w').long("wait").help("Pause the specified groups, but let already running tasks finish by themselves").action(ArgAction::SetTrue))
}

fn kill_command() -> Command {
    Command::new("kill")
        .about("Kill specific running tasks or whole task groups")
        .long_about("Kill specific running tasks or whole task groups.\n\nKills all tasks of the default group when no ids or a specific group are provided.")
        .arg(Arg::new("task_ids").help("Kill these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Kill all running tasks in a group. This also pauses the group").conflicts_with("all"))
        .arg(Arg::new("all").short('a').long("all").help("Kill all running tasks across ALL groups. This also pauses all groups").action(ArgAction::SetTrue))
        .arg(Arg::new("signal").short('s').long("signal").value_name("SIGNAL").help("Send a UNIX signal instead of simply killing the process").long_help("Send a UNIX signal instead of simply killing the process.\n\nDISCLAIMER: This bypasses Pueue's process handling logic! You might enter weird invalid states, use at your own descretion.\n\nThis argument also excepts the integer representation as well as the signal short name. E.g. `sigint`, `int`, or `2` are the same.").value_parser(parse_signal_value))
}

pub fn parse_signal_value(s: &str) -> std::result::Result<Signal, String> {
    s.parse::<Signal>()
}

fn send_command() -> Command {
    Command::new("send")
        .about("Send something to a task. Useful for sending confirmations such as 'y\\n'")
        .arg(Arg::new("task_id").help("The id of the task").required(true).value_name("TASK_ID").value_parser(value_parser!(usize)))
        .arg(Arg::new("input").help("The input that should be sent to the process").required(true).value_name("INPUT"))
}

fn edit_command() -> Command {
    Command::new("edit")
        .about("Adjust editable properties of a task")
        .long_about("Adjust editable properties of a task.\n\nOnly stashed or queued tasks can be edited. A temporary folder folder/file will be opened by your $EDITOR to edit the tasks.")
        .arg(Arg::new("task_ids").help("The ids of all tasks that should be edited").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
}

fn env_command() -> Command {
