        .arg(Arg::new("after").short('a').long("after").value_name("after").help("Start the task once all specified tasks have successfully finished").long_help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well.").num_args(1..).value_parser(value_parser!(usize)))
