        .arg(Arg::new("task_ids").help("Restart these specific tasks").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
        .arg(Arg::new("all_failed").short('a').long("all-failed").help("Restart all failed tasks across all groups").long_help("Restart all failed tasks across all groups.\n\nThis is nice for usage in combination with `-i/--in-place` (or the respective config option).").action(ArgAction::SetTrue).conflicts_with("failed_in_group"))
        .arg(Arg::new("failed_in_group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP").help("Like `--all-failed`, but only restart tasks failed tasks of a specific group"))
        .arg(Arg::new("immediate").short('k').long("immediate").help("Immediately start the tasks, no matter how many open slots there are. This will ignore any dependencies tasks may have").action(ArgAction::SetTrue))
        .arg(Arg::new("stashed").short('s').long("stashed").help("Set the restarted task to a \"Stashed\" state. Useful to avoid immediate execution").action(ArgAction::SetTrue).conflicts_with("immediate"))
        .arg(Arg::new("in_place").short('i').long("in-place").help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks").long_help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks.\n\nThis can also be enabled by default via the `restart_in_place` config option.").action(ArgAction::SetTrue))
        .arg(Arg::new("not_in_place").long("not-in-place").help("Restart the task by creating a new identical tasks. Only necessary if you have the `restart_in_place` configuration set to true").action(ArgAction::SetTrue))
        .arg(Arg::new("edit").short('e').long("edit").help("Edit the task before restarting").action(ArgAction::SetTrue))
