fn send_command() -> Command {
    Command::new("send")
        .about("Send something to a task. Useful for sending confirmations such as 'y\\n'")
        .arg(Arg::new("task_id").help("The id of the task").required(true).value_name("TASK_ID").value_parser(value_parser!(usize)))
        .arg(Arg::new("input").help("The input that should be sent to the process").required(true).value_name("INPUT"))
