fn edit_command() -> Command {
    Command::new("edit")
        .about("Adjust editable properties of a task")
        .long_about("Adjust editable properties of a task.\n\nOnly stashed or queued tasks can be edited. A temporary folder folder/file will be opened by your $EDITOR to edit the tasks.")
        .arg(Arg::new("task_ids").help("The ids of all tasks that should be edited").num_args(0..).value_name("TASK_IDS").value_parser(value_parser!(usize)))
}

