use crate::message::{Group, Task};
use crate::settings::Settings;
use unicode_width::UnicodeWidthChar;

pub fn visible_width(s: &str) -> usize {
    // Strip ANSI for width
    let stripped = strip_ansi(s);
    stripped.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum()
}
pub fn strip_ansi(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            // consume until m
            let mut is_bracket = false;
            for nc in chars.by_ref() {
                if nc == '[' { is_bracket = true; continue; }
                if is_bracket && nc == 'm' { break; }
                if !is_bracket { break; }
            }
        } else {
            out.push(c);
        }
    }
    out
}

pub struct Cell {
    pub text: String,
    pub color: Option<u8>,
}
impl Cell {
    pub fn plain<S: Into<String>>(s: S) -> Self { Self { text: s.into(), color: None } }
    pub fn colored<S: Into<String>>(s: S, code: u8) -> Self { Self { text: s.into(), color: Some(code) } }
}

pub fn format_datetime(dt: chrono::DateTime<chrono::Local>, settings: &Settings) -> String {
    let now = chrono::Local::now();
    if dt.date_naive() == now.date_naive() {
        dt.format(&settings.client.status_time_format).to_string()
    } else {
        dt.format(&settings.client.status_datetime_format).to_string()
    }
}

pub fn group_header(name: &str, group: &Group, colored: bool, settings: &Settings) -> String {
    let status_text = group.status.display();
    if colored {
        let code = match group.status {
            crate::message::GroupStatus::Running => if settings.client.dark_mode { 2 } else { 10 },
            crate::message::GroupStatus::Paused => if settings.client.dark_mode { 3 } else { 11 },
        };
        format!("\x1b[1mGroup {:?}\x1b[0m ({} parallel): \x1b[38;5;{}m{}\x1b[39m", name, group.parallel_tasks, code, status_text)
    } else {
        format!("Group {:?} ({} parallel): {}", name, group.parallel_tasks, status_text)
    }
}

pub fn status_color(task: &Task, settings: &Settings) -> u8 {
    use crate::message::{TaskResult, TaskStatus};
    let dark = settings.client.dark_mode;
    match &task.status {
        TaskStatus::Queued { .. } | TaskStatus::Stashed { .. } => if dark { 3 } else { 11 },
        TaskStatus::Locked { .. } | TaskStatus::Paused { .. } => 15,
        TaskStatus::Running { .. } => if dark { 2 } else { 10 },
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => if dark { 2 } else { 10 },
            _ => if dark { 1 } else { 9 },
        },
    }
}

fn truncate_cell_text(text: &str, max_lines: Option<usize>) -> String {
    if let Some(max) = max_lines {
        if max == 0 { return text.to_string(); }
        let lines: Vec<&str> = text.lines().collect();
        if lines.len() > max {
            let mut kept: Vec<String> = lines[..max].iter().map(|s| s.to_string()).collect();
            if let Some(last) = kept.last_mut() {
                let w = visible_width(last);
                if w > 4 {
                    // approximate original truncation
                    let keep_chars = std::cmp::max(4, w.saturating_sub(3));
                    let truncated: String = last.chars().take(keep_chars).collect();
                    *last = format!("{}...", truncated);
                } else {
                    *last = format!("{}...", last);
                }
            }
            return kept.join("\n");
        }
    }
    text.to_string()
}

pub fn render_table(headers: Vec<String>, rows: Vec<Vec<Cell>>, settings: &Settings, colored: bool) -> String {
    // Apply max_status_lines truncation to cell texts (plain cells and also colored? status text is single line)
    let rows: Vec<Vec<Cell>> = rows.into_iter().map(|row| {
        row.into_iter().map(|mut c| { c.text = truncate_cell_text(&c.text, settings.client.max_status_lines); c }).collect()
    }).collect();

    let cols = headers.len();
    if cols == 0 { return String::new(); }
    let mut widths = vec![0usize; cols];
    for (i, h) in headers.iter().enumerate() {
        for line in h.lines() { widths[i] = widths[i].max(visible_width(line)); }
        if h.is_empty() { /* keep0 */ }
    }
    for row in &rows {
        for (i, cell) in row.iter().enumerate() {
            for line in cell.text.lines() { widths[i] = widths[i].max(visible_width(line)); }
            if cell.text.is_empty() { /* */ }
        }
    }
    // Total width: sum widths + padding 2*cols + separators (cols-1)
    let total = widths.iter().sum::<usize>() + 2 * cols + (cols - 1);
    let mut out = String::new();
    out.push_str(&"─".repeat(total));
    out.push('\n');
    // header row (multi-line not expected)
    out.push_str(&render_row(&headers.iter().map(|h| Cell::plain(h.clone())).collect::<Vec<_>>(), &widths, colored));
    out.push('\n');
    out.push_str(&"═".repeat(total));
    out.push('\n');
    for row in &rows {
        out.push_str(&render_row(row, &widths, colored));
        out.push('\n');
        out.push_str(&"─".repeat(total));
        out.push('\n');
    }
    out
}

fn render_row(cells: &[Cell], widths: &[usize], _colored_enabled: bool) -> String {
    // determine height
    let mut height = 1usize;
    for c in cells { height = height.max(c.text.lines().count().max(1)); }
    let mut lines_out = Vec::new();
    for line_idx in 0..height {
        let mut line = String::new();
        for (i, cell) in cells.iter().enumerate() {
            if i > 0 { line.push(' '); }
            let text_line = cell.text.lines().nth(line_idx).unwrap_or("");
            let w = widths[i];
            let pad_needed = w.saturating_sub(visible_width(text_line));
            if let Some(code) = cell.color {
                if line_idx == 0 {
                    // colored cell: space + text padded + space all inside color
                    line.push_str(&format!("\x1b[38;5;{}m {}{} \x1b[39m", code, text_line, " ".repeat(pad_needed)));
                } else {
                    // subsequent lines of a colored cell are not colored in original? status is single line, so just plain padded empty
                    // For safety, render plain
                    line.push(' ');
                    line.push_str(text_line);
                    line.push_str(&" ".repeat(pad_needed));
                    line.push(' ');
                }
            } else {
                line.push(' ');
                line.push_str(text_line);
                line.push_str(&" ".repeat(pad_needed));
                line.push(' ');
            }
        }
        lines_out.push(line);
    }
    lines_out.join("\n")
}
RS
"}

