fn render_row(cells: &[Cell], widths: &[usize], _colored_enabled: bool) -> String {
    // determine height
    let mut height = 1usize;
    for c in cells { height = height.max(c.text.lines().count().max(1)); }
    let mut lines_out = Vec::new();
    for line_idx in 0..height {
        let mut line = String::new();
        for (i, cell) in cells.iter().enumerate() {
            if i > 0 { line.push(' '); }
            let text_line = cell.text.lines().nth(line_idx).unwrap_or("");
            let w = widths[i];
            let pad_needed = w.saturating_sub(visible_width(text_line));
            if let Some(code) = cell.color {
                if line_idx == 0 {
                    // colored cell: space + text padded + space all inside color
                    line.push_str(&format!("\x1b[38;5;{}m {}{} \x1b[39m", code, text_line, " ".repeat(pad_needed)));
                } else {
                    // subsequent lines of a colored cell are not colored in original? status is single line, so just plain padded empty
                    // For safety, render plain
                    line.push(' ');
