            Column::Id => "Id",
            Column::Status => "Status",
            Column::Command => "Command",
            Column::Label => "Label",
            Column::Path => "Path",
            Column::EnqueueAt => "Enqueue At",
            Column::Dependencies => "Deps",
            Column::Start => "Start",
            Column::End => "End",
        }
    }
}

// canonical display ordering for explicit columns
pub const DISPLAY_ORDER: &[Column] = &[
    Column::Id,
    Column::Status,
    Column::EnqueueAt,
    Column::Dependencies,
    Column::Label,
    Column::Command,
    Column::Path,
    Column::Start,
    Column::End,
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Op {
    Eq,
    Neq,
    Lt,
    Gt,
    Contains,
}

#[derive(Debug, Clone, PartialEq)]
pub enum StatusFilterValue {
    Queued,
    Stashed,
    Paused,
    Running,
    Success,
    Failed,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Filter {
    Status(Op, StatusFilterValue),
    String { column: Column, op: Op, value: String },
    Datetime { column: Column, op: Op, raw: String, kind: DatetimeKind },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DatetimeKind {
    Date,
    Time,
    DateTimeSpace,
    DateTimeConcat,
}

#[derive(Debug, Clone, Default)]
pub struct ParsedQuery {
    pub columns: Option<Vec<Column>>, // deduplicated
    pub filters: Vec<Filter>,
    pub order_by: Option<(Column, bool)>, // (col, descending)
    pub limit: Option<(bool, String)>,     // (is_first, raw_count) count raw may be empty
    pub limit_count: Option<(bool, usize)>, // validated
}

fn pest_error(input: &str, col: usize, expected: &str) -> Report {
    // col is 1-indexed
    let caret_prefix = " ".repeat(col.saturating_sub(1));
    let msg = format!(" --> 1:{}\n  |\n1 | {}\n  | {}^---\n  |\n  = expected {}", col, input, caret_prefix, expected);
    Report::chain(vec!["Failed to parse query".to_string(), msg], "pueue/src/client/commands/state/query/mod.rs:163")
}

struct Parser<'a> {
    input: &'a str,
    bytes: &'a [u8],
    pos: usize,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Stage {
    Start,
    AfterFilterOrColumns,
    AfterOrderColumn,
    AfterDirection,
    AfterLimit,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self { Self { input, bytes: input.as_bytes(), pos: 0 } }
    fn col(&self) -> usize { self.pos + 1 }
    fn eof(&self) -> bool { self.pos >= self.bytes.len() }
    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && (self.bytes[self.pos] == b' ' || self.bytes[self.pos] == b'\t') { self.pos += 1; }
    }
    fn starts_with_ci(&self, prefix: &str) -> bool {
        let b = prefix.as_bytes();
        if self.pos + b.len() > self.bytes.len() { return false; }
        &self.input[self.pos..self.pos + b.len()].to_lowercase() == prefix
    }
    fn consume_ci(&mut self, prefix: &str) -> bool {
        if self.starts_with_ci(prefix) { self.pos += prefix.len(); true } else { false }
    }
    fn peek_rest_lower(&self) -> String { self.input[self.pos..].to_lowercase() }
}

const EXPECTED_AFTER_SEGMENT: &str = "EOI, column_status, column_command, column_label, datetime_filter, order_by, or limit_condition";
const EXPECTED_AFTER_ORDER_COL: &str = "EOI, ascending, descending, or limit_condition";

pub fn parse_query(input: &str) -> Result<ParsedQuery> {
    if input.trim().is_empty() {
        return Ok(ParsedQuery::default());
    }
    let mut p = Parser::new(input);
    let mut query = ParsedQuery::default();
    let mut stage = Stage::Start;
    loop {
        p.skip_ws();
        if p.eof() { break; }
        let seg_start = p.pos;
        // Determine segment type by prefix, regardless of stage for classification of disallowed segments
        // Columns
        if p.starts_with_ci("columns") {
            if stage != Stage::Start {
                return Err(expected_for_stage(input, seg_start, stage));
            }
            // parse columns
            p.pos += "columns".len();
            p.skip_ws();
            // expect eq
            if p.eof() || p.bytes[p.pos] != b'=' {
                return Err(pest_error(input, p.col(), "eq"));
            }
            p.pos += 1; // =
            // columns list
            let mut cols: Vec<Column> = Vec::new();
            loop {
                p.skip_ws();
                let col_start = p.pos;
                match match_column_at(&mut p) {
                    Some(c) => {
                        if !cols.contains(&c) { cols.push(c); }
                    }
                    None => {
                        return Err(pest_error(input, col_start + 1, "column"));
                    }
                }
                p.skip_ws();
                if !p.eof() && p.bytes[p.pos] == b',' {
                    p.pos += 1;
                    continue;
                } else {
                    break;
                }
            }
            query.columns = Some(cols);
            stage = Stage::AfterFilterOrColumns;
            continue;
        }
        // Order_by
        if p.starts_with_ci("order_by") {
            if stage != Stage::Start && stage != Stage::AfterFilterOrColumns {
                return Err(expected_for_stage(input, seg_start, stage));
            }
            p.pos += "order_by".len();
            p.skip_ws();
            let col_start = p.pos;
            let col = match match_column_at(&mut p) {
                Some(c) => c,
                None => return Err(pest_error(input, col_start + 1, "column")),
            };
            query.order_by = Some((col, false));
            stage = Stage::AfterOrderColumn;
            continue;
        }
        // Direction (only recognized in AfterOrderColumn stage, but handle prefix for errors)
        if stage == Stage::AfterOrderColumn && (p.starts_with_ci("asc") || p.starts_with_ci("desc")) {
            let desc = p.starts_with_ci("desc");
            if desc { p.pos += 4; } else { p.pos += 3; }
            if let Some((col, _)) = query.order_by { query.order_by = Some((col, desc)); }
            stage = Stage::AfterDirection;
            continue;
        }
        // Limit
        if p.starts_with_ci("first") || p.starts_with_ci("last") {
            if stage == Stage::AfterLimit {
                return Err(pest_error(input, seg_start + 1, "EOI"));
            }
            // In AfterOrderColumn / AfterDirection / Start / AfterFilter stages limit is allowed
            let is_first = p.starts_with_ci("first");
            if is_first { p.pos += 5; } else { p.pos += 4; }
            // optional number
            let saved = p.pos;
            p.skip_ws();
            let num_start = p.pos;
            while !p.eof() && p.bytes[p.pos].is_ascii_digit() { p.pos += 1; }
            let raw = if p.pos > num_start { input[num_start..p.pos].to_string() } else { String::new() };
            let _ = saved;
            query.limit = Some((is_first, raw));
            stage = Stage::AfterLimit;
            continue;
        }
        // Filters - check datetime columns before status? prefix matching
        // Identify a filter column prefix
        if let Some(filter_col_kind) = classify_filter_at(&p) {
            if stage != Stage::Start && stage != Stage::AfterFilterOrColumns {
                return Err(expected_for_stage(input, seg_start, stage));
            }
            match filter_col_kind {
                FilterKind::Status => {
                    p.pos += "status".len();
                    let op = parse_operator(&mut p, input, &[Op::Eq, Op::Neq], "eq or neq")?;
                    p.skip_ws();
                    let val_start = p.pos;
                    let val = match_status_value(&mut p);
                    match val {
                        Some(v) => query.filters.push(Filter::Status(op, v)),
                        None => {
                            return Err(pest_error(input, val_start + 1, "status_queued, status_stashed, status_paused, status_running, status_success, or status_failed"));
                        }
                    }
                }
                FilterKind::Str(col) => {
                    p.pos += col_name_len(col);
                    let op = parse_operator(&mut p, input, &[Op::Eq, Op::Neq, Op::Contains], "eq, neq, or contains")?;
                    p.skip_ws();
                    // value is rest of string trimmed
                    let value = input[p.pos..].trim().to_string();
                    query.filters.push(Filter::String { column: col, op, value });
                    p.pos = p.bytes.len();
                }
                FilterKind::Datetime(col) => {
                    p.pos += col_name_len(col);
                    let op = parse_operator(&mut p, input, &[Op::Eq, Op::Neq, Op::Lt, Op::Gt], "eq, neq, lt, or gt")?;
                    p.skip_ws();
                    let val_start = p.pos;
                    // token chars digits :- 
                    match parse_datetime_value(&mut p, input) {
                        Some((raw, kind)) => {
                            query.filters.push(Filter::Datetime { column: col, op, raw, kind });
                        }
                        None => {
                            return Err(pest_error(input, val_start + 1, "datetime, date, or time"));
                        }
                    }
                }
            }
            stage = Stage::AfterFilterOrColumns;
            continue;
        }
        // Unrecognized segment
        return Err(expected_for_stage(input, seg_start, stage));
    }

    // Semantic validation for datetime filters in order
    for filter in &query.filters {
        if let Filter::Datetime { raw, kind, .. } = filter {
            validate_datetime(raw, *kind)?;
        }
    }
    // Limit validation
    if let Some((is_first, raw)) = &query.limit {
        if raw.is_empty() || raw.parse::<usize>().is_err() {
            let inner = if raw.is_empty() { "cannot parse integer from empty string".to_string() } else { raw.parse::<usize>().unwrap_err().to_string() };
            return Err(Report::chain(vec!["Expected a number 0 for limit condition".to_string(), inner], "pueue/src/client/commands/state/query/limit.rs:62"));
        }
        let n: usize = raw.parse().unwrap();
        if n == 0 {
            return Err(Report::new("Expected a number >0 for limit condition".to_string(), "pueue/src/client/commands/state/query/limit.rs:65"));
        }
        query.limit_count = Some((*is_first, n));
    }
    Ok(query)
}

fn expected_for_stage(input: &str, seg_start: usize, stage: Stage) -> Report {
    match stage {
        Stage::Start => pest_error(input, seg_start + 1, "query"),
        Stage::AfterFilterOrColumns => pest_error(input, seg_start + 1, EXPECTED_AFTER_SEGMENT),
        Stage::AfterOrderColumn => pest_error(input, seg_start + 1, EXPECTED_AFTER_ORDER_COL),
        Stage::AfterDirection => pest_error(input, seg_start + 1, "EOI or limit_condition"),
        Stage::AfterLimit => pest_error(input, seg_start + 1, "EOI"),
    }
}

fn col_name_len(col: Column) -> usize {
    match col {
        Column::Command => 7,
        Column::Label => 5,
        Column::Start => 5,
        Column::End => 3,
        Column::EnqueueAt => 10,
        _ => 0,
    }
}

#[derive(Clone, Copy)]
enum FilterKind {
    Status,
    Str(Column),
    Datetime(Column),
}

fn classify_filter_at(p: &Parser) -> Option<FilterKind> {
    // longest prefixes first
    if p.starts_with_ci("enqueue_at") { return Some(FilterKind::Datetime(Column::EnqueueAt)); }
    if p.starts_with_ci("command") { return Some(FilterKind::Str(Column::Command)); }
    if p.starts_with_ci("status") { return Some(FilterKind::Status); }
    if p.starts_with_ci("label") { return Some(FilterKind::Str(Column::Label)); }
    if p.starts_with_ci("start") { return Some(FilterKind::Datetime(Column::Start)); }
    if p.starts_with_ci("end") { return Some(FilterKind::Datetime(Column::End)); }
    None
}

fn parse_operator(p: &mut Parser, input: &str, allowed: &[Op], expected: &str) -> Result<Op> {
    p.skip_ws();
    let start = p.pos;
    // try two char ops first
    if p.pos + 1 < p.bytes.len() {
        let two = &input[p.pos..p.pos + 2];
        let op = match two {
            "!=" => Some(Op::Neq),
            "%=" => Some(Op::Contains),
            _ => None,
        };
        if let Some(op) = op {
            if allowed.contains(&op) {
                p.pos += 2;
                return Ok(op);
            } else {
                return Err(pest_error(input, start + 1, expected));
            }
        }
    }
    if !p.eof() {
        let op = match p.bytes[p.pos] as char {
            '=' => Some(Op::Eq),
            '<' => Some(Op::Lt),
            '>' => Some(Op::Gt),
            _ => None,
        };
        if let Some(op) = op {
            if allowed.contains(&op) {
                p.pos += 1;
                return Ok(op);
            } else {
                return Err(pest_error(input, start + 1, expected));
            }
        }
    }
    Err(pest_error(input, start + 1, expected))
}

fn match_status_value(p: &mut Parser) -> Option<StatusFilterValue> {
    let candidates: Vec<(&str, StatusFilterValue)> = vec![
        ("dependencyfailed", StatusFilterValue::Failed), // not applicable
        ("queued", StatusFilterValue::Queued),
        ("stashed", StatusFilterValue::Stashed),
        ("paused", StatusFilterValue::Paused),
        ("running", StatusFilterValue::Running),
        ("success", StatusFilterValue::Success),
        ("failed", StatusFilterValue::Failed),
    ];
    for (name, val) in candidates {
        if p.starts_with_ci(name) {
            p.pos += name.len();
            return Some(val);
        }
    }
    None
}

fn match_column_at(p: &mut Parser) -> Option<Column> {
    // names sorted by length desc to prioritize enqueue_at over end, dependencies over ...
    let names = ["dependencies", "enqueue_at", "command", "status", "label", "start", "path", "end", "id"];
    for name in names {
        if p.starts_with_ci(name) {
            if let Some(col) = Column::from_name(name) {
                p.pos += name.len();
                return Some(col);
            }
        }
    }
    None
}

fn is_digit(b: u8) -> bool { b.is_ascii_digit() }

fn parse_datetime_value(p: &mut Parser, input: &str) -> Option<(String, DatetimeKind)> {
    let start = p.pos;
    let bytes = p.bytes;
    // Try read a datetime token consisting of digits, '-', ':'
    // We need distinguish patterns.
    let mut i = start;
    while i < bytes.len() && (is_digit(bytes[i]) || bytes[i] == b'-' || bytes[i] == b':') { i += 1; }
    if i == start { return None; }
    let token = &input[start..i];
    // datetime concatenated: 4-2-2 + 2:2:2 = length 18? "2020-01-0109:00:00" length 18
    if token.len() == 18 && token.as_bytes()[4] == b'-' && token.as_bytes()[7] == b'-' && token.as_bytes()[12] == b':' && token.as_bytes()[15] == b':' {
        // validate digit positions
        p.pos = i;
        return Some((token.to_string(), DatetimeKind::DateTimeConcat));
    }
    if token.len() == 10 && token.as_bytes()[4] == b'-' && token.as_bytes()[7] == b'-' {
        // date; check following time token
        // save pos
        p.pos = i;
        // Look ahead
        let saved = p.pos;
        p.skip_ws();
        if !p.eof() {
            // next token time pattern digits and colon
            let mut j = p.pos;
            while j < bytes.len() && (is_digit(bytes[j]) || bytes[j] == b':') { j += 1; }
            if j > p.pos {
                let next = &input[p.pos..j];
                if next.contains(':') && next.chars().all(|c| c.is_ascii_digit() || c == ':') {
                    // consume as datetime space
                    let raw = format!("{} {}", token, next);
                    p.pos = j;
                    return Some((raw, DatetimeKind::DateTimeSpace));
                }
            }
        }
        p.pos = saved;
        return Some((token.to_string(), DatetimeKind::Date));
    }
    if (token.len() == 8 || token.len() == 5) && token.as_bytes().get(2) == Some(&b':') {
        // time hh:mm:ss or hh:mm, digits check
        if token.chars().all(|c| c.is_ascii_digit() || c == ':') {
            p.pos = i;
            return Some((token.to_string(), DatetimeKind::Time));
        }
    }
    None
}

fn validate_datetime(raw: &str, kind: DatetimeKind) -> Result<()> {
    match kind {
        DatetimeKind::Date => {
            NaiveDate::parse_from_str(raw, "%Y-%m-%d").map_err(|e| Report::chain(vec!["Expected YYYY-MM-SS date format".to_string(), e.to_string()], "pueue/src/client/commands/state/query/filters.rs:98"))?;
        }
        DatetimeKind::Time => {
            NaiveTime::parse_from_str(raw, "%H:%M:%S").map_err(|e| Report::chain(vec!["Expected hh:mm:ss time format".to_string(), e.to_string()], "pueue/src/client/commands/state/query/filters.rs:86"))?;
        }
        DatetimeKind::DateTimeSpace => {
            NaiveDateTime::parse_from_str(raw, "%Y-%m-%d %H:%M:%S").map_err(|e| Report::chain(vec!["Expected YYYY-MM-SS hh:mm:ss date time format".to_string(), e.to_string()], "pueue/src/client/commands/state/query/filters.rs:93"))?;
        }
        DatetimeKind::DateTimeConcat => {
            NaiveDateTime::parse_from_str(raw, "%Y-%m-%d%H:%M:%S").map_err(|e| Report::chain(vec!["Expected YYYY-MM-SS hh:mm:ss date time format".to_string(), e.to_string()], "pueue/src/client/commands/state/query/filters.rs:93"))?;
        }
    }
    Ok(())
}

pub fn apply_query(tasks: Vec<Task>, query: &ParsedQuery) -> Vec<Task> {
    // filters
    let mut filtered: Vec<Task> = tasks.into_iter().filter(|t| {
        query.filters.iter().all(|f| filter_matches(t, f))
    }).collect();
    // order
    if let Some((col, desc)) = query.order_by {
        filtered.sort_by(|a, b| {
            let ord = compare_tasks(a, b, col);
            if col == Column::Dependencies {
                // inverted bug
                if desc { ord } else { ord.reverse() }
            } else if desc {
                ord.reverse()
            } else { ord }
        });
    }
    // limit
    if let Some((is_first, n)) = query.limit_count {
        if is_first {
            filtered.truncate(n);
        } else {
            if filtered.len() > n {
                let start = filtered.len() - n;
                filtered = filtered.split_off(start);
            }
        }
    }
    filtered
}

fn task_status_category(task: &Task) -> StatusFilterValue {
    match &task.status {
        TaskStatus::Queued { .. } => StatusFilterValue::Queued,
        TaskStatus::Stashed { .. } => StatusFilterValue::Stashed,
        TaskStatus::Paused { .. } => StatusFilterValue::Paused,
        TaskStatus::Running { .. } => StatusFilterValue::Running,
        TaskStatus::Done { result, .. } => {
            if matches!(result, TaskResult::Success) { StatusFilterValue::Success } else { StatusFilterValue::Failed }
        }
        TaskStatus::Locked { previous_status } => {
            // treat as its previous? For filter, likely check previous category? We'll compute recursively by a fake task
            // Simplify: Queued ?? We'll map locked's previous
            // Recreate logic: match previous
            match &**previous_status {
                TaskStatus::Queued { .. } => StatusFilterValue::Queued,
                TaskStatus::Stashed { .. } => StatusFilterValue::Stashed,
                TaskStatus::Paused { .. } => StatusFilterValue::Paused,
                TaskStatus::Running { .. } => StatusFilterValue::Running,
                TaskStatus::Done { result, .. } => if matches!(result, TaskResult::Success) { StatusFilterValue::Success } else { StatusFilterValue::Failed },
                _ => StatusFilterValue::Queued,
            }
        }
    }
}

fn filter_matches(task: &Task, filter: &Filter) -> bool {
    match filter {
        Filter::Status(op, val) => {
            let cat = task_status_category(task);
            let eq = cat == *val;
            match op { Op::Eq => eq, Op::Neq => !eq, _ => false }
        }
        Filter::String { column, op, value } => {
            let field = match column {
                Column::Command => task.command.clone(),
                Column::Label => task.label.clone().unwrap_or_default(),
                _ => String::new(),
            };
            match op {
                Op::Eq => field == *value,
                Op::Neq => field != *value,
                Op::Contains => field.contains(value.as_str()),
                _ => false,
            }
        }
        Filter::Datetime { column, op, raw, kind } => {
            let dt_opt = datetime_for_filter(task, *column);
            let Some(dt) = dt_opt else { return false; };
            match kind {
                DatetimeKind::Date => {
                    let date = NaiveDate::parse_from_str(raw, "%Y-%m-%d").unwrap();
                    let task_date = dt.date_naive();
                    match op {
                        Op::Eq => task_date == date,
                        Op::Lt => task_date < date,
                        Op::Gt => task_date > date,
                        _ => false, // != unsupported for date-only in original
                    }
                }
                DatetimeKind::Time => {
                    let time = NaiveTime::parse_from_str(raw, "%H:%M:%S").unwrap();
                    let task_time = dt.time();
                    match op {
                        Op::Eq => task_time == time,
                        Op::Neq => task_time != time,
                        Op::Lt => task_time < time,
                        Op::Gt => task_time > time,
                        _ => false,
                    }
                }
                DatetimeKind::DateTimeSpace => {
                    let ndt = NaiveDateTime::parse_from_str(raw, "%Y-%m-%d %H:%M:%S").unwrap();
                    let task_ndt = dt.naive_local();
                    match op {
                        Op::Eq => task_ndt == ndt,
                        Op::Neq => task_ndt != ndt,
                        Op::Lt => task_ndt < ndt,
                        Op::Gt => task_ndt > ndt,
                        _ => false,
                    }
                }
                DatetimeKind::DateTimeConcat => {
                    let ndt = NaiveDateTime::parse_from_str(raw, "%Y-%m-%d%H:%M:%S").unwrap();
                    let task_ndt = dt.naive_local();
                    match op {
                        Op::Eq => task_ndt == ndt,
                        Op::Neq => task_ndt != ndt,
                        Op::Lt => task_ndt < ndt,
                        Op::Gt => task_ndt > ndt,
                        _ => false,
                    }
                }
            }
        }
    }
}

fn datetime_for_filter(task: &Task, column: Column) -> Option<chrono::DateTime<chrono::Local>> {
    match column {
        Column::Start => task.status.start(),
        Column::End => task.status.end(),
        Column::EnqueueAt => {
            match &task.status {
                TaskStatus::Stashed { enqueue_at } => *enqueue_at,
                _ => None,
            }
        }
        _ => None,
    }
}

fn status_rank(task: &Task) -> (usize, usize) {
    match &task.status {
        TaskStatus::Stashed { .. } => (0, 0),
        TaskStatus::Locked { .. } => (1, 0),
        TaskStatus::Queued { .. } => (2, 0),
        TaskStatus::Paused { .. } => (3, 0),
        TaskStatus::Running { .. } => (4, 0),
        TaskStatus::Done { result, .. } => {
            let sub = match result {
                TaskResult::Failed(_) => 0,
                TaskResult::Errored => 1,
                TaskResult::Killed => 2,
                TaskResult::DependencyFailed => 3,
                TaskResult::FailedToSpawn(_) => 4,
                TaskResult::Success => 5,
            };
            (5, sub)
        }
    }
}

fn compare_tasks(a: &Task, b: &Task, col: Column) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match col {
        Column::Id => a.id.cmp(&b.id),
        Column::Status => status_rank(a).cmp(&status_rank(b)),
        Column::Command => a.command.cmp(&b.command),
        Column::Label => a.label.clone().unwrap_or_default().cmp(&b.label.clone().unwrap_or_default()),
        Column::Path => a.path.cmp(&b.path),
        Column::EnqueueAt => {
            let ka = enqueue_order_key(a);
            let kb = enqueue_order_key(b);
            ka.cmp(&kb)
        }
        Column::Dependencies => a.dependencies.cmp(&b.dependencies),
        Column::Start => a.status.start().cmp(&b.status.start()),
        Column::End => a.status.end().cmp(&b.status.end()),
    }
}

fn enqueue_order_key(task: &Task) -> chrono::DateTime<chrono::Local> {
    match &task.status {
        TaskStatus::Queued { enqueued_at } => *enqueued_at,
        TaskStatus::Running { enqueued_at, .. } | TaskStatus::Paused { enqueued_at, .. } | TaskStatus::Done { enqueued_at, .. } => *enqueued_at,
        TaskStatus::Stashed { enqueue_at } => enqueue_at.unwrap_or_else(|| chrono::DateTime::<chrono::Local>::MAX_UTC.with_timezone(&chrono::Local)),
        _ => chrono::DateTime::<chrono::Local>::MAX_UTC.with_timezone(&chrono::Local),
    }
}
