// ---------- simple commands ----------
pub fn add(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let path_arg = m.get_one::<String>("working_directory").cloned();
    let path = if let Some(p) = path_arg {
        std::fs::canonicalize(&p).map_err(|e| {
            Report::chain(vec!["Failed to canonicalize given working directory path".to_string(), e.to_string()], "/workspace/pueue/src/client/commands/add.rs:42")
        })?
    } else {
        std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."))
    };
    let commands: Vec<String> = m.get_many::<String>("command").map(|v| v.cloned().collect()).unwrap_or_default();
    let escape = m.get_flag("escape");
    let command = if escape {
        commands.iter().map(|c| shell_escape(c)).collect::<Vec<_>>().join(" ")
    } else {
        commands.join(" ")
    };
    let envs: std::collections::HashMap<String, String> = std::env::vars().collect();
    let group = m.get_one::<String>("group").cloned().unwrap_or_else(|| "default".to_string());
    let enqueue_at = m.get_one::<chrono::DateTime<chrono::Local>>("delay").cloned();
    let dependencies: Vec<usize> = m.get_many::<usize>("after").map(|v| v.copied().collect()).unwrap_or_default();
    let priority = m.get_one::<i32>("priority").copied();
    let label = m.get_one::<String>("label").cloned();
    let task = AddTask {
        command,
        path,
        envs,
        start_immediately: m.get_flag("immediate"),
        stashed: m.get_flag("stashed"),
        group,
        enqueue_at,
        dependencies,
        priority,
        label,
    };
    let request = Request::Add(task);
    let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/add.rs:73")?;
    match resp {
        Response::AddedTask(added) => {
            if m.get_flag("print_task_id") {
                println!("{}", added.task_id);
            } else {
                println!("{}", added.message);
            }
            if m.get_flag("follow") {
                // Follow the added task if running
                // Use follow logic with task_id
                return follow_with_id(client, ctx, Some(added.task_id), m.get_one::<usize>("lines").copied());
            }
            Ok(())
        }
        other => {
            handle_response(other);
            Ok(())
        }
    }
}

pub fn shell_escape(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    // Determine if quoting needed: safe chars are alphanumerics and _-/.,:=+@% ??? Investigate later.
    // Use a conservative approximation matching shell_escape crate: if all chars are in safe set, return as is.
    let safe = s.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ',' | ':' | '/' | '=' | '+' ));
    if safe {
        return s.to_string();
    }
    // Special handling for '!' like observed: 'a'\!'b'
    // General algorithm: wrap in single quotes, replace ' with '\'' , and ! with '\!'
    // But observed for a string containing ' and ! separately...
    // We'll implement standard shell_escape unix escape:
    let mut out = String::new();
    out.push('\'');
    for c in s.chars() {
        match c {
            '\'' => {
                out.push_str("'\\''");
            }
            '!' => {
                out.push_str("'\\!'");
                // need reopen quote? The observed: 'a'\!'b' - they close ', escape !, reopen '
                // Our current building: we already opened, we added "'\!'": that closes, escapes, but does not reopen.
                // To match, after that we should push a single quote to reopen if more chars follow.
                // We'll handle by pushing '\'' as reopen marker; final closing will close it.
                // However this double counts... Simplify with a state machine below instead.
                // This code path is replaced.
                let _ = out;
            }
            _ => out.push(c),
        }
    }
    out.push('\'');
    // Rebuild correctly
    let mut result = String::new();
    result.push('\'');
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            result.push_str("'\\''");
        } else if c == '!' {
            result.push_str("'\\!'");
        } else {
            result.push(c);
        }
        i += 1;
    }
    result.push('\'');
    result
}

