pub fn shell_escape(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    // Determine if quoting needed: safe chars are alphanumerics and _-/.,:=+@% ??? Investigate later.
    // Use a conservative approximation matching shell_escape crate: if all chars are in safe set, return as is.
    let safe = s.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ',' | ':' | '/' | '=' | '+' ));
    if safe {
        return s.to_string();
    }
    // Special handling for '!' like observed: 'a'\!'b'
    // General algorithm: wrap in single quotes, replace ' with '\'' , and ! with '\!'
    // But observed for a string containing ' and ! separately...
    // We'll implement standard shell_escape unix escape:
    let mut out = String::new();
    out.push('\'');
    for c in s.chars() {
        match c {
            '\'' => {
                out.push_str("'\\''");
            }
            '!' => {
                out.push_str("'\\!'");
                // need reopen quote? The observed: 'a'\!'b' - they close ', escape !, reopen '
                // Our current building: we already opened, we added "'\!'": that closes, escapes, but does not reopen.
                // To match, after that we should push a single quote to reopen if more chars follow.
                // We'll handle by pushing '\'' as reopen marker; final closing will close it.
                // However this double counts... Simplify with a state machine below instead.
                // This code path is replaced.
                let _ = out;
            }
            _ => out.push(c),
        }
    }
    out.push('\'');
    // Rebuild correctly
    let mut result = String::new();
    result.push('\'');
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\'' {
            result.push_str("'\\''");
        } else if c == '!' {
            result.push_str("'\\!'");
        } else {
            result.push(c);
        }
        i += 1;
    }
    result.push('\'');
    result
}

