        if !query_string.is_empty() {
            let parsed = query::parse_query(query_string)?;
            tasks_vec = query::apply_query(tasks_vec, &parsed);
        }
        let mut out_tasks = BTreeMap::new();
        for t in tasks_vec { out_tasks.insert(t.id, t); }
        let out_state = State { tasks: out_tasks, groups: state.groups.clone() };
        println!("{}", serde_json::to_string(&out_state).unwrap());
        return Ok(());
    }

    // Non-json: parse query if present (must happen even for empty / missing group)
    let parsed_query = if !query_string.is_empty() {
        Some(query::parse_query(query_string)?)
    } else { None };

    if let Some(group_name) = group_opt {
        if !state.groups.contains_key(&group_name) {
            println!();
            eprintln!("There exists no group \"{}\"", group_name);
            return Ok(());
        }
        // tasks for group
        let mut tasks: Vec<Task> = state.tasks.values().filter(|t| t.group == group_name).cloned().collect();
        if let Some(q) = &parsed_query {
            tasks = query::apply_query(tasks, q);
        }
        // print single group
        print_group_section(&state, &group_name, &tasks, ctx, parsed_query.as_ref(), true);
        return Ok(());
    }

    // No group
    if state.tasks.is_empty() {
        // panic if default not present
        if !state.groups.contains_key("default") {
            crate::error::panic_report("called `Option::unwrap()` on a `None` value", "pueue/src/client/commands/state/mod.rs:137");
        }
        let group = &state.groups["default"];
        // header + blank line + message
        println!("{}", display::group_header("default", group, ctx.colored(), settings));
        println!();
        println!("Task list is empty. Add tasks with `pueue add -- [cmd]`");
        return Ok(());
    }

    // Has tasks
    // Pathological panics
    if state.groups.is_empty() {
        crate::error::panic_report("called `Option::unwrap()` on a `None` value", "pueue/src/client/commands/state/mod.rs:153");
    }
    // If any task's group missing from groups, panic 175 (except groups.is_empty handled above)
    if state.tasks.values().any(|t| !state.groups.contains_key(&t.group)) {
        crate::error::panic_report("called `Option::unwrap()` on a `None` value", "pueue/src/client/commands/state/mod.rs:175");
    }

    let mut all_tasks: Vec<Task> = state.tasks.values().cloned().collect();
    if let Some(q) = &parsed_query {
        all_tasks = query::apply_query(all_tasks, q);
    }
    if all_tasks.is_empty() {
        println!();
        return Ok(());
    }
    // group tasks preserving order, groups in state.groups order (BTree sorted)
    let mut sections: Vec<(String, Vec<Task>)> = Vec::new();
    for group_name in state.groups.keys() {
        let tasks_for: Vec<Task> = all_tasks.iter().filter(|t| &t.group == group_name).cloned().collect();
        if !tasks_for.is_empty() {
            sections.push((group_name.clone(), tasks_for));
        }
    }
    for (idx, (group_name, tasks)) in sections.iter().enumerate() {
        if idx > 0 { println!(); }
        print_group_section(&state, group_name, tasks, ctx, parsed_query.as_ref(), false);
    }
    Ok(())
}

fn print_group_section(state: &State, group_name: &str, tasks: &[Task], ctx: &Ctx, parsed_query: Option<&query::ParsedQuery>, is_single_group: bool) {
    let settings = &ctx.settings;
    let group = &state.groups[group_name];
    println!("{}", display::group_header(group_name, group, ctx.colored(), settings));
    if tasks.is_empty() {
        println!("Task list is empty. Add tasks with `pueue add -g {} -- [cmd]`", group_name);
        return;
    }
    // Build columns
    let (_headers, table) = build_status_table(tasks, ctx, parsed_query);
    print!("{}", table.trim_end_matches('\n'));
    println!();
    // The table builder returns trailing newline; above reproduces? We'll adjust in caller usage: print_group_section used also for no-group; there print! of trimmed + println gives final newline.
    let _ = is_single_group;
}

fn build_status_table(tasks: &[Task], ctx: &Ctx, parsed_query: Option<&query::ParsedQuery>) -> (Vec<String>, String) {
    let settings = &ctx.settings;
    // Columns selection
    #[derive(Debug, Clone, Copy, PartialEq)]
    enum ColKind { Id, Status, Prio, EnqueueAt, Deps, Label, Command, Path, Start, End }
    let mut cols: Vec<ColKind> = Vec::new();
    if let Some(q) = parsed_query {
        if let Some(selected) = &q.columns {
            for dc in query::DISPLAY_ORDER {
                if selected.contains(dc) {
                    cols.push(match dc {
                        Column::Id => ColKind::Id,
                        Column::Status => ColKind::Status,
                        Column::Command => ColKind::Command,
                        Column::Label => ColKind::Label,
                        Column::Path => ColKind::Path,
                        Column::EnqueueAt => ColKind::EnqueueAt,
                        Column::Dependencies => ColKind::Deps,
                        Column::Start => ColKind::Start,
                        Column::End => ColKind::End,
                    });
                }
            }
        } else {
            // default
            cols = default_cols(tasks);
        }
    } else {
        cols = default_cols(tasks);
    }

    fn default_cols(tasks: &[Task]) -> Vec<ColKind> {
        let mut cols = vec![ColKind::Id, ColKind::Status];
        if tasks.iter().any(|t| t.priority != 0) { cols.push(ColKind::Prio); }
        if tasks.iter().any(|t| matches!(&t.status, TaskStatus::Stashed { enqueue_at: Some(_) })) { cols.push(ColKind::EnqueueAt); }
        if tasks.iter().any(|t| !t.dependencies.is_empty()) { cols.push(ColKind::Deps); }
        if tasks.iter().any(|t| t.label.is_some()) { cols.push(ColKind::Label); }
        cols.push(ColKind::Command);
        cols.push(ColKind::Path);
        cols.push(ColKind::Start);
        cols.push(ColKind::End);
        cols
    }

    let headers: Vec<String> = cols.iter().map(|c| match c {
        ColKind::Id => "Id".to_string(),
        ColKind::Status => "Status".to_string(),
        ColKind::Prio => "Prio".to_string(),
        ColKind::EnqueueAt => "Enqueue At".to_string(),
        ColKind::Deps => "Deps".to_string(),
        ColKind::Label => "Label".to_string(),
        ColKind::Command => "Command".to_string(),
        ColKind::Path => "Path".to_string(),
        ColKind::Start => "Start".to_string(),
        ColKind::End => "End".to_string(),
    }).collect();

    let rows: Vec<Vec<Cell>> = tasks.iter().map(|task| {
        cols.iter().map(|c| {
            match c {
                ColKind::Id => Cell::plain(task.id.to_string()),
                ColKind::Status => {
                    let text = task.status.display_status();
                    if ctx.colored() { Cell::colored(text, display::status_color(task, settings)) } else { Cell::plain(text) }
                }
                ColKind::Prio => Cell::plain(task.priority.to_string()),
                ColKind::EnqueueAt => {
                    let txt = match &task.status {
                        TaskStatus::Stashed { enqueue_at: Some(dt) } => display::format_datetime(*dt, settings),
                        _ => String::new(),
                    };
                    Cell::plain(txt)
                }
                ColKind::Deps => Cell::plain(task.dependencies.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(", ")),
                ColKind::Label => Cell::plain(task.label.clone().unwrap_or_default()),
                ColKind::Command => Cell::plain(if settings.client.show_expanded_aliases { task.command.clone() } else { task.original_command.clone() }),
                ColKind::Path => Cell::plain(task.path.to_string_lossy().to_string()),
                ColKind::Start => Cell::plain(task.status.start().map(|dt| display::format_datetime(dt, settings)).unwrap_or_default()),
                ColKind::End => Cell::plain(task.status.end().map(|dt| display::format_datetime(dt, settings)).unwrap_or_default()),
            }
        }).collect()
    }).collect();

    let table = display::render_table(headers.clone(), rows, settings, ctx.colored());
    (headers, table)
}

pub fn group_command_handler(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    // Determine request based on subcommand
    let (request, sub_matches) = match m.subcommand() {
        Some(("add", sub)) => {
            let name = sub.get_one::<String>("name").cloned().unwrap_or_default();
            let parallel = sub.get_one::<usize>("parallel").copied();
            (Request::Group(GroupMessage::Add { name, parallel_tasks: parallel }), Some(sub))
        }
        Some(("remove", sub)) => {
            let name = sub.get_one::<String>("name").cloned().unwrap_or_default();
            (Request::Group(GroupMessage::Remove(name)), Some(sub))
        }
        _ => (Request::Group(GroupMessage::List), None),
    };
    let _ = sub_matches;
    let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/group.rs:27")?;
    match resp {
        Response::Group(group_resp) => {
            let json = m.get_flag("json");
            if json {
                println!("{}", serde_json::to_string(&group_resp.groups).unwrap());
            } else {
                for (name, group) in &group_resp.groups {
                    println!("{}", display::group_header(name, group, ctx.colored(), &ctx.settings));
                }
            }
            Ok(())
        }
        other => {
            handle_response(other);
            Ok(())
        }
    }
}

pub fn parallel_handler(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let _ = ctx;
    if let Some(amount) = m.get_one::<usize>("parallel_tasks").copied() {
        let group = m.get_one::<String>("group").cloned().unwrap_or_else(|| "default".to_string());
        let req = Request::Parallel { parallel_tasks: amount, group };
        let resp = client.send_and_receive(&req, "/workspace/pueue/src/client/commands/parallel.rs:27")?;
        handle_response(resp);
        Ok(())
    } else {
        let req = Request::Group(GroupMessage::List);
        let resp = client.send_and_receive(&req, "/workspace/pueue/src/client/commands/parallel.rs:27")?;
        handle_response(resp);
        Ok(())
    }
}

