use clap::{Arg, Command};

pub fn generate(cmd: &mut Command, bin: &str, out: &mut dyn std::io::Write) {
    // Build command in place? clap_complete generators call build.
    cmd.build();
    let mut text = String::new();
    text.push_str("module completions {\n\n");
    // completers for value enums
    gen_value_completers(cmd, bin, &mut text, bin);
    text.push('\n');
    gen_externs(cmd, bin, &mut text, bin);
    text.push_str("}\n\nexport use completions *\n");
    let _ = out.write_all(text.as_bytes());
}

fn gen_value_completers(cmd: &Command, _bin: &str, out: &mut String, root: &str) {
    // Recursively find args with possible values
    fn walk(cmd: &Command, path: &str, out: &mut String, root: &str) {
        for arg in cmd.get_arguments() {
            let vals: Vec<String> = arg.get_value_parser().get_possible_values().iter().map(|v| v.get_name().to_string()).collect();
            if !vals.is_empty() {
                let name = arg.get_id();
                // completer name is root + arg id with spaces?
                // Original: "nu-complete pueue color" for root --color, and "nu-complete pueue completions shell" etc.
                let full = if path == root { format!("{} {}", root, name) } else { format!("{} {}", path, name) };
                // dedup handled by caller? skip duplicates
                let values = vals.iter().map(|v| format!("\"{}\"", v)).collect::<Vec<_>>().join(" ");
                out.push_str(&format!("  def \"nu-complete {}\" [] {{\n    [ {} ]\n  }}\n\n", full, values));
            }
        }
        for sub in cmd.get_subcommands() {
            if sub.get_name() == "help" { continue; }
            let subpath = format!("{} {}", path, sub.get_name());
            walk(sub, &subpath, out, root);
        }
    }
    walk(cmd, root, out, root);
    // remove trailing double newlines handling later
}

fn gen_externs(cmd: &Command, _bin: &str, out: &mut String, root: &str) {
    fn extern_for(cmd: &Command, path: &str, out: &mut String, root: &str) {
        // comment: about first line? original uses about with newlines replaced by spaces and ?? We'll see comparisons
        let about = cmd.get_about().map(|s| s.to_string()).unwrap_or_default();
        let about_oneline = about.replace('\n', " ");
        if !about_oneline.is_empty() {
            out.push_str(&format!("  # {}\n", about_oneline));
        }
        out.push_str(&format!("  export extern \"{}\" [\n", path));
        // flags first (in argument declaration order, help/version auto at end? original order: defined args, then help, version if root)
        let mut args: Vec<&Arg> = cmd.get_arguments().collect();
        // clap_complete nushell sorts? It iterates options, then positionals.
        let mut options: Vec<&Arg> = Vec::new();
        let mut positionals: Vec<&Arg> = Vec::new();
        for a in args.drain(..) {
            if a.get_long().is_some() || a.get_short().is_some() {
                // exclude help/version auto? clap adds them as args but generation includes them from cmd's auto args.
                options.push(a);
            } else {
                positionals.push(a);
            }
        }
        // Determine maximal signature length for alignment
        let mut sigs: Vec<(String, String)> = Vec::new(); // (signature, help)
        for a in &options {
            let help = a.get_help().map(|s| s.to_string().replace('\n', " ")).unwrap_or_default();
