use crate::client::Client;
use crate::commands::{get_state, handle_response, Ctx};
use crate::error::{Report, Result};
use crate::message::*;
use std::collections::BTreeMap;

pub fn subcommand_debug(matches: &clap::ArgMatches, _pretty: bool) -> String {
    // Approximate Debug representation of parsed subcommand for TRACE logging.
    // Format: `Name { field: value, ... }` similar to derived Debug of CLI structs.
    // This is used only for -vvv tracing.
    match matches.subcommand() {
        Some((name, sub)) => {
            let struct_name = {
                let mut chars = name.chars();
                match chars.next() {
                    Some(c) => c.to_ascii_uppercase().to_string() + chars.as_str(),
                    None => name.to_string(),
                }
            };
            // Replace '-' with '_' and capitalize segments for env set etc handled by caller flattening below.
            // Build a very rough representation based on arg ids present in definition.
            let mut fields: Vec<String> = Vec::new();
            for arg in sub.arg_ids() {
                let id = arg.as_str();
                if id == "help" || id == "version" { continue; }
                let val = format_arg_value(sub, id);
                fields.push(format!("{}: {}", id, val));
            }
            if fields.is_empty() {
                format!("{}", struct_name)
            } else {
                format!("{} {{ {} }}", struct_name, fields.join(", "))
            }
        }
        None => "Status { query: [], json: false, group: None }".to_string(),
    }
}

fn format_arg_value(matches: &clap::ArgMatches, id: &str) -> String {
    // Try typed values in order.
    // We don't know type; use ids reflection: try to get many strings/values from matches via value access by string form Debug of raw.
    // clap ArgMatches Debug for value? Use get_one::<String> may panic if type mismatch; catch via checking common typed getters using panic hooks is risky.
    // Instead special-case known ids.
    match id {
        "verbose" | "color" | "config" | "profile" => String::new(),
        _ => {
            // Many values are String/bool/usize/DateTime - we attempt String first with catch_unwind.
            let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                matches.get_many::<String>(id).map(|v| format!("{:?}", v.collect::<Vec<_>>()))
            }));
            if let Ok(Some(s)) = res { return s; }
            // bool flag
            // get_flag panics if arg is not bool typed in clap? It checks action; for value args it would panic - catch.
            let resb = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| matches.get_flag(id)));
            if let Ok(b) = resb { return format!("{:?}", b); }
            format!("{:?}", id)
        }
    }
}

pub fn env_command(client: &mut Client, m: &clap::ArgMatches) -> Result<()> {
    let request = match m.subcommand() {
        Some(("set", sub)) => {
            let task_id = *sub.get_one::<usize>("task_id").unwrap_or(&0);
            let key = sub.get_one::<String>("key").cloned().unwrap_or_default();
            let value = sub.get_one::<String>("value").cloned().unwrap_or_default();
            Request::Env(EnvMessage::Set { task_id, key, value })
        }
        Some(("unset", sub)) => {
            let task_id = *sub.get_one::<usize>("task_id").unwrap_or(&0);
            let key = sub.get_one::<String>("key").cloned().unwrap_or_default();
            Request::Env(EnvMessage::Unset { task_id, key })
        }
        _ => return Ok(()),
    };
    let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/env.rs:26")?;
    handle_response(resp);
    Ok(())
}

// ---------- Wait ----------
fn task_category(task: &Task) -> String {
    match &task.status {
        TaskStatus::Locked { .. } => "Locked".to_string(),
        TaskStatus::Stashed { .. } => "Stashed".to_string(),
        TaskStatus::Queued { .. } => "Queued".to_string(),
        TaskStatus::Running { .. } => "Running".to_string(),
        TaskStatus::Paused { .. } => "Paused".to_string(),
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => "Success".to_string(),
            _ => "Failed".to_string(),
        },
    }
}

fn result_message(task: &Task) -> String {
    match &task.status {
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => format!("Task {} succeeded with 0", task.id),
            TaskResult::Failed(code) => format!("Task {} failed with {}", task.id, code),
            TaskResult::FailedToSpawn(_) => format!("Task {} failed to spawn", task.id),
            TaskResult::DependencyFailed => format!("Task {} failed due to failed dependencies", task.id),
            TaskResult::Errored => format!("Task {} experienced an IO error.", task.id),
            TaskResult::Killed => format!("Task {} has been killed", task.id),
        },
        _ => String::new(),
    }
}

fn now_time() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}

fn target_reached(task: &Task, target: Option<crate::cli::WaitStatus>) -> bool {
    use crate::cli::WaitStatus;
    match target {
        None => task.status.is_done(),
        Some(WaitStatus::Done) => task.status.is_done(),
        Some(WaitStatus::Success) => matches!(&task.status, TaskStatus::Done { result: TaskResult::Success, .. }),
        Some(WaitStatus::Running) => {
            matches!(task.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. }) || task.status.is_done()
        }
        Some(WaitStatus::Queued) => {
            matches!(task.status, TaskStatus::Queued { .. } | TaskStatus::Running { .. } | TaskStatus::Paused { .. }) || task.status.is_done()
        }
    }
}

pub fn wait(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let _ = ctx;
    let task_ids: Vec<usize> = m.get_many::<usize>("task_ids").map(|v| v.copied().collect()).unwrap_or_default();
    let group = m.get_one::<String>("group").cloned();
    let all = m.get_flag("all");
    let selection = crate::commands::selection(task_ids.clone(), group.clone(), all);
    let quiet = m.get_flag("quiet");
    let target = m.get_one::<crate::cli::WaitStatus>("status").copied();

    let mut previous: BTreeMap<usize, String> = BTreeMap::new();
    loop {
        let state = get_state(client)?;
        // selection filtering
        let selected: Vec<Task> = state.tasks.values().filter(|t| match &selection {
            TaskSelection::TaskIds(ids) => ids.contains(&t.id),
            TaskSelection::Group(g) => &t.group == g,
            TaskSelection::All => true,
        }).cloned().collect();

        if selected.is_empty() {
            eprintln!("No tasks found for selection {:?}", selection);
            return Ok(());
        }

        // Messages
        for task in &selected {
            let cur_cat = task_category(task);
            if let Some(prev) = previous.get(&task.id) {
                if prev != &cur_cat {
                    if !quiet {
                        if task.status.is_done() {
                            println!("{} - {}", now_time(), result_message(task));
                        } else {
                            println!("{} - Task {} changed from {} to {}", now_time(), task.id, prev, cur_cat);
                        }
                    }
                }
            } else {
                // first observation
                if !quiet && matches!(task.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. }) {
                    println!("{} - Found active Task {} with status {}", now_time(), task.id, cur_cat);
                }
            }
            previous.insert(task.id, cur_cat);
        }

        // termination
        if selected.iter().all(|t| target_reached(t, target)) {
            return Ok(());
        }
        // if target is Success and all tasks are done (but not all success), exit 1
        if matches!(target, Some(crate::cli::WaitStatus::Success)) && selected.iter().all(|t| t.status.is_done()) {
            std::process::exit(1);
        }

        std::thread::sleep(std::time::Duration::from_secs(2));
    }
}

// ---------- Reset ----------
pub fn reset(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let _ = ctx;
    let state = get_state(client)?;
    let groups_arg: Vec<String> = m.get_many::<String>("groups").map(|v| v.cloned().collect()).unwrap_or_default();
    let force = m.get_flag("force");

    let target_groups_list: Vec<String> = if groups_arg.is_empty() {
        state.groups.keys().cloned().collect()
    } else {
        groups_arg.clone()
    };

    if !force {
        // Determine active tasks in target groups
        let target_set: std::collections::HashSet<String> = target_groups_list.iter().cloned().collect();
        let mut active: Vec<&Task> = state.tasks.values().filter(|t| {
            // If groups arg empty and state groups empty, target is All - then all tasks count
            let in_target = if groups_arg.is_empty() && state.groups.is_empty() { true } else { target_set.contains(&t.group) };
            in_target && matches!(t.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. })
        }).collect();
        active.sort_by_key(|t| t.id);
        if !active.is_empty() {
            let list = active.iter().map(|t| format!("task{}", t.id)).collect::<Vec<_>>().join(", ");
            eprint!("You are trying to remove running tasks: {}", list);
            // prompt
            if !crate::commands::ask_for_confirmation() {
                eprint!("\nAborted!");
                std::process::exit(1);
            }
        }
    }

    let target = if target_groups_list.is_empty() {
        ResetTarget::All
    } else {
        ResetTarget::Groups(target_groups_list)
    };
    let request = Request::Reset { target };
    let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/reset.rs:48")?;
    handle_response(resp);
    Ok(())
}

// ---------- Restart ----------
pub fn restart(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let state = get_state(client)?;

    let task_ids: Vec<usize> = m.get_many::<usize>("task_ids").map(|v| v.copied().collect()).unwrap_or_default();
    let all_failed = m.get_flag("all_failed");
    let failed_in_group = m.get_one::<String>("failed_in_group").cloned();
    let immediate = m.get_flag("immediate");
    let stashed = m.get_flag("stashed");
    let edit_flag = m.get_flag("edit");
    let in_place_flag = m.get_flag("in_place");
    let not_in_place_flag = m.get_flag("not_in_place");

    let in_place = if not_in_place_flag { false } else if in_place_flag { true } else { ctx.settings.client.restart_in_place };

    // Determine tasks to restart (in state order) and missing ids logic
    let mut restarted_display: Vec<usize> = Vec::new();
    let mut not_found: Vec<usize> = Vec::new();

    // Collect task objects to restart (state iteration order)
    let mut tasks_to_restart: Vec<Task> = Vec::new();
    if all_failed {
        for task in state.tasks.values() {
            if is_failed(task) { tasks_to_restart.push(task.clone()); }
        }
        restarted_display = tasks_to_restart.iter().map(|t| t.id).collect();
    } else if let Some(g) = &failed_in_group {
        for task in state.tasks.values() {
            if is_failed(task) && &task.group == g { tasks_to_restart.push(task.clone()); }
        }
        restarted_display = tasks_to_restart.iter().map(|t| t.id).collect();
    } else {
        if task_ids.is_empty() {
            return Err(Report::new("Please provide the ids of the tasks you want to restart.".to_string(), "/workspace/pueue/src/client/commands/restart.rs:89"));
        }
        // not found and display in input order, deduped? Original shows duplicates in display but we replicate: display contains ids that exist, in input order, including duplicates.
        for id in &task_ids {
            if state.tasks.contains_key(id) {
                restarted_display.push(*id);
            } else {
                if !not_found.contains(id) { not_found.push(*id); }
                // original not_found display: for duplicate missing ? They showed [5] for single. For duplicates of missing, unknown. Keep as input order with dedup? Test earlier not_found list for restart 5 was [5]. We'll keep input order without dedup for missing? But for display of restarted, duplicates preserved.
                // Adjust: not_found should preserve input occurrences? We'll handle below by recomputing.
            }
        }
        // recompute not_found in input order (including duplicates)
        not_found = task_ids.iter().filter(|id| !state.tasks.contains_key(id)).copied().collect();
        // unique state-ordered tasks
        let mut seen = std::collections::HashSet::new();
        for task in state.tasks.values() {
            if task_ids.contains(&task.id) && seen.insert(task.id) {
                tasks_to_restart.push(task.clone());
            }
        }
    }

    // Edit handling
    let mut edited_map: BTreeMap<usize, EditableTask> = BTreeMap::new();
    if edit_flag && !tasks_to_restart.is_empty() {
        // Build editable tasks from restart tasks
        let editable: Vec<EditableTask> = tasks_to_restart.iter().map(|t| EditableTask {
            id: t.id,
            command: t.original_command.clone(),
            path: t.path.clone(),
            label: t.label.clone(),
            priority: t.priority,
        }).collect();
        let edited = crate::edit::edit_tasks(&editable, &ctx.settings)?;
        // Validate edited ids
        let original_ids: std::collections::HashSet<usize> = tasks_to_restart.iter().map(|t| t.id).collect();
        for et in &edited {
            if !original_ids.contains(&et.id) {
                return Err(Report::new(format!("Found unexpected task id during editing: {}", et.id), "/workspace/pueue/src/client/commands/restart.rs:117"));
            }
            edited_map.insert(et.id, et.clone());
        }
        // If edited list is empty, original tasks remain (as observed)
        // edited_map stays; merging below will use original if not present
    }

    let mut any_restarted = false;
    if in_place {
        // Build Restart tasks
        let restart_tasks: Vec<RestartTask> = tasks_to_restart.iter().map(|t| {
            if let Some(et) = edited_map.get(&t.id) {
                RestartTask { task_id: et.id, original_command: et.command.clone(), path: et.path.clone(), label: et.label.clone(), priority: et.priority }
            } else {
                RestartTask { task_id: t.id, original_command: t.original_command.clone(), path: t.path.clone(), label: t.label.clone(), priority: t.priority }
            }
        }).collect();

        // In-place with all_failed/failed_in_group and no tasks still sends request (as observed)
        let should_send = if all_failed || failed_in_group.is_some() { true } else { !tasks_to_restart.is_empty() };
        if should_send {
            let request = Request::Restart { tasks: restart_tasks, start_immediately: immediate, stashed };
            let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/restart.rs:169")
                .map_err(|e| e)?;
            match resp {
                Response::Failure(text) => {
                    return Err(Report::new(text, "/workspace/pueue/src/client/commands/restart.rs:170"));
                }
                _ => {}
            }
            any_restarted = !tasks_to_restart.is_empty();
        }
    } else {
        // not in place: one Add per task (state order)
        for task in &tasks_to_restart {
            let (cmd, path, label, prio) = if let Some(et) = edited_map.get(&task.id) {
                (et.command.clone(), et.path.clone(), et.label.clone(), et.priority)
            } else {
                (task.original_command.clone(), task.path.clone(), task.label.clone(), task.priority)
            };
            let add_task = AddTask {
                command: cmd,
                path,
                envs: task.envs.clone(),
                start_immediately: immediate,
                stashed,
                group: task.group.clone(),
                enqueue_at: None,
                dependencies: Vec::new(),
                priority: Some(prio),
                label,
