use std::collections::BTreeMap;

pub fn subcommand_debug(matches: &clap::ArgMatches, _pretty: bool) -> String {
    // Approximate Debug representation of parsed subcommand for TRACE logging.
    // Format: `Name { field: value, ... }` similar to derived Debug of CLI structs.
