pub fn restart(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let state = get_state(client)?;

    let task_ids: Vec<usize> = m.get_many::<usize>("task_ids").map(|v| v.copied().collect()).unwrap_or_default();
    let all_failed = m.get_flag("all_failed");
    let failed_in_group = m.get_one::<String>("failed_in_group").cloned();
    let immediate = m.get_flag("immediate");
    let stashed = m.get_flag("stashed");
    let edit_flag = m.get_flag("edit");
    let in_place_flag = m.get_flag("in_place");
    let not_in_place_flag = m.get_flag("not_in_place");

    let in_place = if not_in_place_flag { false } else if in_place_flag { true } else { ctx.settings.client.restart_in_place };

    // Determine tasks to restart (in state order) and missing ids logic
    let mut restarted_display: Vec<usize> = Vec::new();
    let mut not_found: Vec<usize> = Vec::new();

    // Collect task objects to restart (state iteration order)
    let mut tasks_to_restart: Vec<Task> = Vec::new();
