    } else if let Some(g) = &failed_in_group {
        for task in state.tasks.values() {
            if is_failed(task) && &task.group == g { tasks_to_restart.push(task.clone()); }
        }
        restarted_display = tasks_to_restart.iter().map(|t| t.id).collect();
    } else {
        if task_ids.is_empty() {
            return Err(Report::new("Please provide the ids of the tasks you want to restart.".to_string(), "/workspace/pueue/src/client/commands/restart.rs:89"));
        }
        // not found and display in input order, deduped? Original shows duplicates in display but we replicate: display contains ids that exist, in input order, including duplicates.
        for id in &task_ids {
            if state.tasks.contains_key(id) {
                restarted_display.push(*id);
            } else {
                if !not_found.contains(id) { not_found.push(*id); }
