                group: task.group.clone(),
                enqueue_at: None,
                dependencies: Vec::new(),
                priority: Some(prio),
                label,
            };
            let request = Request::Add(add_task);
            let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/restart.rs:161")?;
            match resp {
                Response::Failure(text) => {
                    return Err(Report::new(text, "/workspace/pueue/src/client/commands/restart.rs:162"));
                }
                _ => {}
            }
            any_restarted = true;
        }
    }

    if !not_found.is_empty() {
