    for t in tasks {
        map.insert(t.id, TomlEditableTask { id: t.id, command: t.command.clone(), path: t.path.clone(), label: t.label.clone(), priority: t.priority });
    }
    let toml_string = toml::to_string(&map).map_err(|e| {
        // Unlikely
        Report::new(format!("Some error occurred. \nFailed to serialize tasks to toml:\n{}", e), "pueue/src/client/commands/edit.rs:135")
    })?;
    std::fs::write(&file_path, toml_string).map_err(|e| {
        Report::chain(vec![format!("I/O error at path {:?} while writing temporary file:\n{}", file_path.to_string_lossy(), e)], "pueue/src/client/commands/edit.rs:133")
    })?;

    let editor = get_editor()?;
    run_editor(&editor, &file_path)?;

    // Read back
    let content_bytes = std::fs::read(&file_path).map_err(|e| {
        Report::chain(vec![format!("I/O error at path {:?} while reading temporary file:\n{}", file_path.to_string_lossy(), e)], "pueue/src/client/commands/edit.rs:133")
    })?;
    let content = String::from_utf8_lossy(&content_bytes).to_string();
    let parsed: std::result::Result<BTreeMap<usize, TomlEditableTask>, _> = toml::from_str(&content);
    let parsed_map = parsed.map_err(|e| {
        Report::new(format!("Some error occurred. \nFailed to deserialize tasks to toml:\n{}\n", e), "pueue/src/client/commands/edit.rs:135")
        // Original toml error ends with a blank line in output; our message may have extra newline. Adjust later.
    })?;
    let mut result: Vec<EditableTask> = parsed_map.values().map(|t| EditableTask { id: t.id, command: t.command.clone(), path: t.path.clone(), label: t.label.clone(), priority: t.priority }).collect();
    result.sort_by_key(|t| t.id);
    // Cleanup temp dir (best effort)
    let _ = std::fs::remove_dir_all(&temp_dir);
    Ok(result)
}

// ----- FILES mode -----
fn edit_tasks_files(tasks: &[EditableTask], _settings: &Settings) -> Result<Vec<EditableTask>> {
    let temp_dir = make_temp_dir()?;
    // Write per-task directories
    for t in tasks {
        let dir = temp_dir.join(t.id.to_string());
        std::fs::create_dir_all(&dir).map_err(|e| Report::new(format!("{}", e), "pueue/src/client/commands/edit.rs:200"))?;
        // files: command, label, path, priority (no newline)
        write_file(&dir.join("command"), &t.command)?;
        write_file(&dir.join("label"), t.label.as_deref().unwrap_or(""))?;
        write_file(&dir.join("path"), &t.path.to_string_lossy())?;
        write_file(&dir.join("priority"), &t.priority.to_string())?;
    }

    let editor = get_editor()?;
    // In files mode, editor is invoked with temp dir as argument
    run_editor(&editor, &temp_dir)?;

    // Read back for each original task
    let mut result = Vec::new();
    for t in tasks {
        let dir = temp_dir.join(t.id.to_string());
        let command = read_trimmed_file(&dir.join("command"), "command", 253)?;
        let label_str = read_trimmed_file(&dir.join("label"), "label", 260)?;
        let path_str = read_trimmed_file(&dir.join("path"), "path", 270)?;
        let priority_str = read_trimmed_file(&dir.join("priority"), "priority", 280)?;
        let priority: i32 = priority_str.parse().map_err(|e: std::num::ParseIntError| {
            Report::chain(vec![format!("Failed to parse priority string '{}' into an integer for task {}", priority_str, t.id), e.to_string()], "pueue/src/client/commands/edit.rs:297")
        })?;
        let label = if label_str.is_empty() { None } else { Some(label_str) };
        result.push(EditableTask { id: t.id, command, path: PathBuf::from(path_str), label, priority });
    }
    let _ = std::fs::remove_dir_all(&temp_dir);
    Ok(result)
}

