    std::fs::write(path, content).map_err(|e| Report::new(format!("{}", e), "pueue/src/client/commands/edit.rs:200"))
}

fn read_trimmed_file(path: &Path, name: &str, loc_line: u32) -> Result<String> {
    let content = std::fs::read_to_string(path).map_err(|e| {
        let location = format!("pueue/src/client/commands/edit.rs:{}", loc_line);
        // leak location string to get &'static - we use match on name to select static
        let loc: &'static str = match name {
            "command" => "pueue/src/client/commands/edit.rs:253",
            "label" => "pueue/src/client/commands/edit.rs:263",
            "path" => "pueue/src/client/commands/edit.rs:273",
            "priority" => "pueue/src/client/commands/edit.rs:283",
            _ => "pueue/src/client/commands/edit.rs:253",
        };
        let _ = location;
        Report::chain(vec![format!("I/O error at path {:?} while reading {} file:\n{}", path.to_string_lossy(), name, e)], loc)
