fn make_temp_dir() -> Result<PathBuf> {
    // tempfile style: /tmp/.tmpXXXXXX (6 random alphanumeric)
    for _ in 0..100 {
        let suffix: String = (0..6).map(|_| {
            let chars = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
            let idx = (rand_u8() as usize) % chars.len();
            chars[idx] as char
        }).collect();
        let path = std::env::temp_dir().join(format!(".tmp{}", suffix));
        if std::fs::create_dir(&path).is_ok() {
            return Ok(path);
        }
    }
    Err(Report::new("Failed to create temporary directory".to_string(), "pueue/src/client/commands/edit.rs:100"))
