        };
        // Only print when task is active or done
        if matches!(task.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. } | TaskStatus::Done { .. }) {
            // Open log file
            let mut file = match std::fs::File::open(&log_path) {
                Ok(f) => f,
                Err(e) => {
                    eprintln!("Failed to get log file handles: I/O error at path {:?} while getting log file handle:\n{}", log_path.to_string_lossy(), e);
                    return Ok(());
                }
            };
            if printed_offset.is_none() {
                // first print
                let mut content = Vec::new();
                let _ = file.read_to_end(&mut content);
                let total_len = content.len() as u64;
                let output = select_last_lines(&content, lines_opt);
                let _ = std::io::stdout().write_all(&output);
                let _ = std::io::stdout().flush();
                printed_offset = Some(total_len);
            } else {
                let offset = printed_offset.unwrap();
                let _ = file.seek(SeekFrom::Start(offset));
                let mut new_content = Vec::new();
                let _ = file.read_to_end(&mut new_content);
                if !new_content.is_empty() {
                    let _ = std::io::stdout().write_all(&new_content);
                    let _ = std::io::stdout().flush();
                    printed_offset = Some(offset + new_content.len() as u64);
                }
            }
            if task.status.is_done() {
                break;
            }
        }
        std::thread::sleep(std::time::Duration::from_millis(500));
    }
    Ok(())
}

fn select_last_lines(content: &[u8], lines_opt: Option<usize>) -> Vec<u8> {
    if let Some(n) = lines_opt {
        if n == 0 { return Vec::new(); }
        // split into lines keeping terminators
        let mut lines: Vec<&[u8]> = Vec::new();
        let mut start = 0usize;
        for i in 0..content.len() {
            if content[i] == b'\n' {
                lines.push(&content[start..=i]);
                start = i + 1;
            }
        }
        if start < content.len() {
            lines.push(&content[start..]);
        }
        if lines.len() > n {
            lines = lines[lines.len() - n..].to_vec();
        }
        lines.concat()
    } else {
        content.to_vec()
    }
}
