use crate::client::Client;
use crate::commands::{handle_response, Ctx};
use crate::error::Result;
use crate::message::*;

pub fn log_command(client: &mut Client, ctx: &Ctx, m: &clap::ArgMatches) -> Result<()> {
    let task_ids: Vec<usize> = m.get_many::<usize>("task_ids").map(|v| v.copied().collect()).unwrap_or_default();
    let group = m.get_one::<String>("group").cloned();
    let all = m.get_flag("all");
    let selection = crate::commands::selection(task_ids, group.clone(), all);
    let json = m.get_flag("json");
    let full = m.get_flag("full");
    let lines_opt = m.get_one::<usize>("lines").copied();

    // Determine lines: if full -> None, else if lines given -> Some, else default Some(15?) Wait request lines field is usize? In request capture lines: Some(15) default, None if full, Some(n) if lines.
    // Request's lines field type in LogMessage: Option<usize> but capture showed 15 as integer, not option wrapper difference in CBOR - Some(15) encodes as 15, None as null.
    let req_lines: Option<usize> = if full { None } else if let Some(l) = lines_opt { Some(l) } else { Some(15) };
    let request = Request::Log { tasks: selection.clone(), send_logs: false, lines: req_lines };

    let resp = client.send_and_receive(&request, "/workspace/pueue/src/client/commands/log/mod.rs:46")?;
    match resp {
        Response::Log(logs) => {
            if json {
                // Need to trim outputs according to lines/full before json? Original json prints logs map as received trimmed client-side?
                // For now print serde_json of logs (Map). Our LogEntry struct serializes as {task, output}
                // If output is None, client would read local logs and include them in json.
                let logs = fill_local_logs(logs, ctx, req_lines);
                println!("{}", serde_json::to_string(&logs).unwrap());
                return Ok(());
            }
            if logs.is_empty() {
                match &selection {
                    TaskSelection::TaskIds(_) => eprintln!("There are no finished tasks for your specified ids"),
                    TaskSelection::Group(g) => eprintln!("There are no finished tasks for group '{}'", g),
                    TaskSelection::All => eprintln!("There are no finished tasks"),
                }
                return Ok(());
            }
            // Print logs
            print_logs(logs, ctx, req_lines);
            Ok(())
        }
        other => {
            handle_response(other);
            Ok(())
        }
    }
}

fn fill_local_logs(logs: std::collections::BTreeMap<usize, LogEntry>, ctx: &Ctx, _lines: Option<usize>) -> std::collections::BTreeMap<usize, LogEntry> {
    // If output is None, read local log file (if exists) and use it as output
    let mut map = logs;
    for (id, entry) in map.iter_mut() {
        if entry.output.is_none() {
            let path = ctx.settings.shared().pueue_directory.join("task_logs").join(format!("{}.log", id));
            if let Ok(content) = std::fs::read_to_string(&path) {
                entry.output = Some(content);
            }
        }
    }
    map
}

fn print_logs(logs: std::collections::BTreeMap<usize, LogEntry>, ctx: &Ctx, lines: Option<usize>) {
    // Print format guessed; refine after probing original with correct Log type (currently unknown)
    let logs = fill_local_logs(logs, ctx, lines);
    let mut first = true;
    for (id, entry) in logs.iter() {
        if !first { println!(); }
        first = false;
        println!("Task {} - {}:", id, entry.task.original_command);
        if let Some(output) = &entry.output {
            let trimmed = trim_lines(output, lines);
            print!("{}", trimmed);
            if !trimmed.ends_with('\n') && !trimmed.is_empty() { println!(); }
        }
    }
}

fn trim_lines(output: &str, lines: Option<usize>) -> String {
    if let Some(n) = lines {
        let all: Vec<&str> = output.lines().collect();
        if all.len() > n {
            let kept = &all[all.len() - n..];
            let mut s = kept.join("\n");
            if output.ends_with('\n') { s.push('\n'); }
            return s;
        }
    }
    output.to_string()
}
