use clap::{ArgAction, Command};

pub fn generate(cmd: &mut Command, bin: &str, out: &mut dyn std::io::Write) {
    cmd.build();
    let mut text = String::new();
    text.push_str("module completions {\n\n");
    gen_externs(cmd, &mut text, bin);
    text.push_str("}\n\nexport use completions *\n");
    let _ = out.write_all(text.as_bytes());
}

fn gen_externs(cmd: &Command, out: &mut String, root: &str) {
    fn extern_for(cmd: &Command, path: &str, out: &mut String) {
        let about = cmd.get_about().map(|s| s.to_string()).unwrap_or_default();
        let about_oneline = about.replace('\n', " ");
        if !about_oneline.is_empty() {
            out.push_str(&format!("  # {}\n", about_oneline));
        }
        out.push_str(&format!("  export extern \"{}\" [\n", path));
        let mut sigs: Vec<(String, String)> = Vec::new();
        let mut positionals: Vec<(String, String)> = Vec::new();
        for a in cmd.get_arguments() {
            let help = a.get_help().map(|s| s.to_string().replace('\n', " ")).unwrap_or_default();
            if let Some(long) = a.get_long() {
                let mut sig = format!("--{}", long);
                if let Some(s) = a.get_short() { sig.push_str(&format!("(-{})", s)); }
                let takes = matches!(a.get_action(), ArgAction::Set | ArgAction::Append);
                if takes { sig.push_str(": string"); }
                sigs.push((sig, help));
            } else if a.get_short().is_some() {
                // short only shouldn't happen
            } else {
                // positional, skip help/version auto positionals none
                let id = a.get_id().to_string();
                if id == "help" { continue; }
                let mut sig = String::new();
                sig.push_str(&id);
                sig.push_str(": string");
                positionals.push((sig, help));
            }
        }
        sigs.extend(positionals);
        let maxlen = sigs.iter().map(|(s, _)| s.len()).max().unwrap_or(0);
        for (sig, help) in &sigs {
            if help.is_empty() {
                out.push_str(&format!("    {}\n", sig));
            } else {
                out.push_str(&format!("    {:<width$} # {}\n", sig, help, width = maxlen));
            }
        }
        out.push_str("  ]\n\n");
        for sub in cmd.get_subcommands() {
            let subpath = format!("{} {}", path, sub.get_name());
            extern_for(sub, &subpath, out);
        }
    }
    extern_for(cmd, root, out);
}
