//! Minimal terminal size detection for Unix, implemented for this project.
//! It reports the current terminal dimensions using the `TIOCGWINSZ` ioctl.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct Ws {
    ws_row: libc::c_ushort,
    ws_col: libc::c_ushort,
    ws_xpixel: libc::c_ushort,
    ws_ypixel: libc::c_ushort,
}

fn size_from_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    let mut ws = Ws::default();
    let rc = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) };
    if rc == 0 && ws.ws_col > 0 {
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    } else {
        None
    }
}

/// Returns the size of the terminal, if available.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_from_fd(libc::STDOUT_FILENO)
        .or_else(|| size_from_fd(libc::STDERR_FILENO))
        .or_else(|| size_from_fd(libc::STDIN_FILENO))
}

/// Returns the size of the terminal from a specific file descriptor.
pub fn terminal_size_of(fd: std::os::unix::io::RawFd) -> Option<(Width, Height)> {
    size_from_fd(fd)
}
