{"command":"cd /workspace && cat > src/nushell.rs <<'RS'
use clap::{Arg, ArgAction, Command};

pub fn generate(cmd: &mut Command, bin: &str, out: &mut dyn std::io::Write) {
    cmd.build();
    let mut text = String::new();
    text.push_str("module completions {\n\n");
    gen_command(cmd, bin, &mut text);
    text.push_str("}\n\nexport use completions *\n");
    let _ = out.write_all(text.as_bytes());
}

fn real_subcommands<'a>(cmd: &'a Command) -> Vec<&'a Command> {
    cmd.get_subcommands().filter(|c| c.get_name() != "help").collect()
}

fn gen_command(cmd: &Command, path: &str, out: &mut String) {
    // completers for this command's args
    for arg in cmd.get_arguments() {
        let vals = arg.get_possible_values();
        if !vals.is_empty() {
            let vlist = vals.iter().map(|v| format!("\"{}\"", v.get_name())).collect::<Vec<_>>().join(" ");
            out.push_str(&format!("  def \"nu-complete {} {}\" [] {{\n    [ {} ]\n  }}\n\n", path, arg.get_id(), vlist));
        }
    }
    emit_extern(cmd, path, out, false);
    let subs = real_subcommands(cmd);
    for sub in &subs {
        let subpath = format!("{} {}", path, sub.get_name());
        gen_command(sub, &subpath, out);
    }
    if !subs.is_empty() {
        // synthetic help subtree
        // `help` extern itself
        emit_synthetic(path, "help", "Print this message or the help of the given subcommand(s)", out);
        for sub in &subs {
            // leaf for help <sub>
            let sub_about = sub.get_about().map(|s| s.to_string()).unwrap_or_default();
            emit_synthetic(path, &format!("help {}", sub.get_name()), &sub_about, out);
            // children of sub as leaves under help
            for subsub in real_subcommands(sub) {
                let ss_about = subsub.get_about().map(|s| s.to_string()).unwrap_or_default();
                // path for synthetic is "{path} help {sub} {subsub}" ; our emit_synthetic takes a suffix relative to path
                emit_synthetic(path, &format!("help {} {}", sub.get_name(), subsub.get_name()), &ss_about, out);
            }
        }
        emit_synthetic(path, "help help", "Print this message or the help of the given subcommand(s)", out);
    }
}

fn emit_synthetic(base_path: &str, suffix: &str, about: &str, out: &mut String) {
    let full = format!("{} {}", base_path, suffix);
    let about_one = about.replace('\n', " ");
    if !about_one.is_empty() {
        out.push_str(&format!("  # {}\n", about_one));
    }
    out.push_str(&format!("  export extern \"{}\" [\n  ]\n\n", full));
}

fn emit_extern(cmd: &Command, path: &str, out: &mut String, _synthetic: bool) {
    let about = cmd.get_about().map(|s| s.to_string()).unwrap_or_default().replace('\n', " ");
    if !about.is_empty() {
        out.push_str(&format!("  # {}\n", about));
    }
    if path.contains(' ') {
        out.push_str(&format!("  export extern \"{}\" [\n", path));
    } else {
        out.push_str(&format!("  export extern {} [\n", path));
    }
    let mut sigs: Vec<(String, String)> = Vec::new();
    let mut positionals: Vec<(String, String)> = Vec::new();
    for a in cmd.get_arguments() {
        // Skip auto help subcommand positional? none
        let help = a.get_help().map(|s| s.to_string().replace('\n', " ")).unwrap_or_default();
        if let Some(long) = a.get_long() {
            let mut sig = format!("--{}", long);
            if let Some(short) = a.get_short() {
                sig.push_str(&format!("(-{})", short));
            }
            let takes = matches!(a.get_action(), ArgAction::Set | ArgAction::Append);
            if takes {
                sig.push_str(&format!(": {}", arg_type(a, path)));
            }
            sigs.push((sig, help));
        } else if a.get_short().is_some() {
            // not expected
        } else {
            // positional: help/version are long args, already handled. "help" subcommand is not an argument.
            let id = a.get_id().as_str();
            if id == "version" { continue; }
            let mut sig = String::new();
            let multiple = a.get_num_args().map(|r| r.max_values() > 1).unwrap_or(false) || matches!(a.get_action(), ArgAction::Append);
            if multiple { sig.push_str("..."); }
            sig.push_str(id);
            if !multiple && !a.is_required_set() { sig.push_str("?"); }
            sig.push_str(&format!(": {}", arg_type(a, path)));
            positionals.push((sig, help));
        }
    }
    sigs.extend(positionals);
    for (sig, help) in &sigs {
        if help.is_empty() {
            out.push_str(&format!("    {}\n", sig));
        } else if sig.len() >= 26 {
            out.push_str(&format!("    {} # {}\n", sig, help));
        } else {
            out.push_str(&format!("    {:<26} # {}\n", sig, help));
        }
    }
    out.push_str("  ]\n\n");
}

fn arg_type(a: &Arg, path: &str) -> String {
    let vals = a.get_possible_values();
    if !vals.is_empty() {
        return format!("string@\"nu-complete {} {}\"", path, a.get_id());
    }
    match a.get_value_hint() {
        clap::ValueHint::AnyPath | clap::ValueHint::FilePath | clap::ValueHint::DirPath => "path".to_string(),
        _ => "string".to_string(),
    }
}
