{"command":"cd /workspace && cat > src/subdebug.rs <<'RS'
use std::fmt;

#[derive(Clone)]
pub enum Dbg {
    Str(String),
    Raw(String),
    Bool(bool),
    Int(i64),
    UInt(usize),
    List(Vec<Dbg>),
    Opt(Option<Box<Dbg>>),
    Struct(String, Vec<(String, Dbg)>),
}

impl fmt::Debug for Dbg {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Dbg::Str(s) => write!(f, "{:?}", s),
            Dbg::Raw(s) => write!(f, "{}", s),
            Dbg::Bool(b) => write!(f, "{:?}", b),
            Dbg::Int(v) => write!(f, "{:?}", v),
            Dbg::UInt(v) => write!(f, "{:?}", v),
            Dbg::List(items) => {
                let mut l = f.debug_list();
                for i in items { l.entry(i); }
                l.finish()
            }
            Dbg::Opt(o) => {
                match o {
                    Some(inner) => {
                        let mut t = f.debug_tuple("Some");
                        t.field(&**inner);
                        t.finish()
                    }
                    None => write!(f, "None"),
                }
            }
            Dbg::Struct(name, fields) => {
                let mut s = f.debug_struct(name);
                for (n, v) in fields { s.field(n, v); }
                s.finish()
            }
        }
    }
}

pub fn opt_str(v: Option<String>) -> Dbg { Dbg::Opt(v.map(|s| Box::new(Dbg::Str(s)))) }
pub fn opt_raw<T: fmt::Display>(v: Option<T>) -> Dbg { Dbg::Opt(v.map(|x| Box::new(Dbg::Raw(format!("{}", x)))) ) }
pub fn list_str(v: Vec<String>) -> Dbg { Dbg::List(v.into_iter().map(Dbg::Str).collect()) }
pub fn list_usize(v: Vec<usize>) -> Dbg { Dbg::List(v.into_iter().map(Dbg::UInt).collect()) }

pub fn build(matches: &clap::ArgMatches) -> Dbg {
    match matches.subcommand() {
        Some(("add", sub)) => Dbg::Struct("Add".into(), vec![
            ("command".into(), list_str(get_strings(sub, "command"))),
            ("working_directory".into(), opt_str(sub.get_one::<String>("working_directory").cloned())),
            ("escape".into(), Dbg::Bool(sub.get_flag("escape"))),
            ("start_immediately".into(), Dbg::Bool(sub.get_flag("immediate"))),
            ("follow".into(), Dbg::Bool(sub.get_flag("follow"))),
            ("stashed".into(), Dbg::Bool(sub.get_flag("stashed"))),
            ("delay_until".into(), opt_raw(sub.get_one::<chrono::DateTime<chrono::Local>>("delay").copied())),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("dependencies".into(), list_usize(get_usizes(sub, "after"))),
            ("priority".into(), Dbg::Opt(sub.get_one::<i32>("priority").copied().map(|v| Box::new(Dbg::Int(v as i64))))),
            ("label".into(), opt_str(sub.get_one::<String>("label").cloned())),
            ("print_task_id".into(), Dbg::Bool(sub.get_flag("print_task_id"))),
        ]),
        Some(("remove", sub)) => Dbg::Struct("Remove".into(), vec![("task_ids".into(), list_usize(get_usizes(sub, "task_ids")))]),
        Some(("switch", sub)) => Dbg::Struct("Switch".into(), vec![
            ("task_id_1".into(), Dbg::UInt(*sub.get_one::<usize>("task_id_1").unwrap_or(&0))),
            ("task_id_2".into(), Dbg::UInt(*sub.get_one::<usize>("task_id_2").unwrap_or(&0))),
        ]),
        Some(("stash", sub)) => Dbg::Struct("Stash".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("delay_until".into(), opt_raw(sub.get_one::<chrono::DateTime<chrono::Local>>("delay").copied())),
        ]),
        Some(("enqueue", sub)) => Dbg::Struct("Enqueue".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("delay_until".into(), opt_raw(sub.get_one::<chrono::DateTime<chrono::Local>>("delay").copied())),
        ]),
        Some(("start", sub)) => Dbg::Struct("Start".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
        ]),
        Some(("restart", sub)) => Dbg::Struct("Restart".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("all_failed".into(), Dbg::Bool(sub.get_flag("all_failed"))),
            ("failed_in_group".into(), opt_str(sub.get_one::<String>("failed_in_group").cloned())),
            ("start_immediately".into(), Dbg::Bool(sub.get_flag("immediate"))),
            ("stashed".into(), Dbg::Bool(sub.get_flag("stashed"))),
            ("in_place".into(), Dbg::Bool(sub.get_flag("in_place"))),
            ("not_in_place".into(), Dbg::Bool(sub.get_flag("not_in_place"))),
            ("edit".into(), Dbg::Bool(sub.get_flag("edit"))),
        ]),
        Some(("pause", sub)) => Dbg::Struct("Pause".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("wait".into(), Dbg::Bool(sub.get_flag("wait"))),
        ]),
        Some(("kill", sub)) => Dbg::Struct("Kill".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("signal".into(), Dbg::Opt(sub.get_one::<crate::message::Signal>("signal").copied().map(|s| Box::new(Dbg::Raw(format!("{:?}", s))))),
        ]),
        Some(("send", sub)) => Dbg::Struct("Send".into(), vec![
            ("task_id".into(), Dbg::UInt(*sub.get_one::<usize>("task_id").unwrap_or(&0))),
            ("input".into(), Dbg::Str(sub.get_one::<String>("input").cloned().unwrap_or_default())),
        ]),
        Some(("edit", sub)) => Dbg::Struct("Edit".into(), vec![("task_ids".into(), list_usize(get_usizes(sub, "task_ids")))]),
        Some(("env", sub)) => {
            let cmd = match sub.subcommand() {
                Some(("set", s)) => Dbg::Struct("Set".into(), vec![
                    ("task_id".into(), Dbg::UInt(*s.get_one::<usize>("task_id").unwrap_or(&0))),
                    ("key".into(), Dbg::Str(s.get_one::<String>("key").cloned().unwrap_or_default())),
                    ("value".into(), Dbg::Str(s.get_one::<String>("value").cloned().unwrap_or_default())),
                ]),
                Some(("unset", s)) => Dbg::Struct("Unset".into(), vec![
                    ("task_id".into(), Dbg::UInt(*s.get_one::<usize>("task_id").unwrap_or(&0))),
                    ("key".into(), Dbg::Str(s.get_one::<String>("key").cloned().unwrap_or_default())),
                ]),
                _ => Dbg::Raw("".into()),
            };
            Dbg::Struct("Env".into(), vec![("cmd".into(), cmd)])
        }
        Some(("group", sub)) => {
            let cmd_dbg = match sub.subcommand() {
                Some(("add", s)) => Dbg::Opt(Some(Box::new(Dbg::Struct("Add".into(), vec![
                    ("name".into(), Dbg::Str(s.get_one::<String>("name").cloned().unwrap_or_default())),
                    ("parallel".into(), Dbg::Opt(s.get_one::<usize>("parallel").copied().map(|v| Box::new(Dbg::UInt(v))))),
                ])))),
                Some(("remove", s)) => Dbg::Opt(Some(Box::new(Dbg::Struct("Remove".into(), vec![
                    ("name".into(), Dbg::Str(s.get_one::<String>("name").cloned().unwrap_or_default())),
                ])))),
                _ => Dbg::Opt(None),
            };
            Dbg::Struct("Group".into(), vec![
                ("json".into(), Dbg::Bool(sub.get_flag("json"))),
                ("cmd".into(), cmd_dbg),
            ])
        }
        Some(("status", sub)) => Dbg::Struct("Status".into(), vec![
            ("query".into(), list_str(get_strings(sub, "query"))),
            ("json".into(), Dbg::Bool(sub.get_flag("json"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
        ]),
        Some(("log", sub)) => Dbg::Struct("Log".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("json".into(), Dbg::Bool(sub.get_flag("json"))),
            ("lines".into(), Dbg::Opt(sub.get_one::<usize>("lines").copied().map(|v| Box::new(Dbg::UInt(v))))),
            ("full".into(), Dbg::Bool(sub.get_flag("full"))),
        ]),
        Some(("follow", sub)) => Dbg::Struct("Follow".into(), vec![
            ("task_id".into(), Dbg::Opt(sub.get_one::<usize>("task_id").copied().map(|v| Box::new(Dbg::UInt(v))))),
            ("lines".into(), Dbg::Opt(sub.get_one::<usize>("lines").copied().map(|v| Box::new(Dbg::UInt(v))))),
        ]),
        Some(("wait", sub)) => Dbg::Struct("Wait".into(), vec![
            ("task_ids".into(), list_usize(get_usizes(sub, "task_ids"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
            ("all".into(), Dbg::Bool(sub.get_flag("all"))),
            ("quiet".into(), Dbg::Bool(sub.get_flag("quiet"))),
            ("status".into(), Dbg::Opt(sub.get_one::<crate::cli::WaitStatus>("status").copied().map(|s| Box::new(Dbg::Raw(match s { crate::cli::WaitStatus::Queued => "Queued".into(), crate::cli::WaitStatus::Running => "Running".into(), crate::cli::WaitStatus::Done => "Done".into(), crate::cli::WaitStatus::Success => "Success".into(), }))))),
        ]),
        Some(("clean", sub)) => Dbg::Struct("Clean".into(), vec![
            ("successful_only".into(), Dbg::Bool(sub.get_flag("successful_only"))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
        ]),
        Some(("reset", sub)) => Dbg::Struct("Reset".into(), vec![
            ("groups".into(), list_str(get_strings(sub, "groups"))),
            ("force".into(), Dbg::Bool(sub.get_flag("force"))),
        ]),
        Some(("shutdown", _)) => Dbg::Raw("Shutdown".into()),
        Some(("parallel", sub)) => Dbg::Struct("Parallel".into(), vec![
            ("parallel_tasks".into(), Dbg::Opt(sub.get_one::<usize>("parallel_tasks").copied().map(|v| Box::new(Dbg::UInt(v))))),
            ("group".into(), opt_str(sub.get_one::<String>("group").cloned())),
        ]),
        Some((name, _)) => Dbg::Raw(name.to_string()),
        None => Dbg::Struct("Status".into(), vec![
            ("query".into(), Dbg::List(vec![])),
            ("json".into(), Dbg::Bool(false)),
            ("group".into(), Dbg::Opt(None)),
        ]),
    }
}

fn get_strings(m: &clap::ArgMatches, id: &str) -> Vec<String> { m.get_many::<String>(id).map(|v| v.cloned().collect()).unwrap_or_default() }
fn get_usizes(m: &clap::ArgMatches, id: &str) -> Vec<usize> { m.get_many::<usize>(id).map(|v| v.copied().collect()).unwrap_or_default() }
